const reproQuestions = [
  // ===== REPRO: Hormones =====
  { id: "re1", category: "GnRH", q: "Where is GnRH produced and what does it stimulate, and why do continuous GnRH agonists like leuprolide, goserelin, and nafarelin function clinically as antagonists?", a: "GnRH is produced by the hypothalamus and stimulates LH and FSH secretion from the anterior pituitary. Continuous administration of GnRH agonists causes desensitization of the GnRH receptor at the anterior pituitary, leading to DECREASED LH and FSH secretion. GnRH secretion is inhibited by estrogen, androgen, and progesterone - negative feedback." },
  { id: "re2", category: "GnRH", q: "What is the mechanism for amenorrhea in anorexia?", a: "DECREASED GnRH pulsation. Leptin is required for adequate GnRH pulsation; in anorexia the patient is hungry, so leptin is low. DECREASED GnRH pulsation causes LH and FSH to both be DECREASED, leading to reduced ovarian hormone production and follicle stimulation." },
  { id: "re3", category: "GnRH", q: "What happens to GnRH secretion in menopause, Turner syndrome, Klinefelter, or premature ovarian failure, and why?", a: "INCREASED GnRH secretion due to DECREASED negative feedback. These are conditions of PRIMARY hypogonadism - the organ itself (ovary or testis) is the reason for the hormone change, versus CENTRAL where the hypothalamus or anterior pituitary is at fault." },
  { id: "re4", category: "GnRH", q: "Why does androgen-insensitivity syndrome cause INCREASED GnRH, and what do exogenous anabolic steroids do to the axis?", a: "AIS: androgen cannot exert negative feedback at androgen receptors at the hypothalamus, so GnRH rises. Anabolic steroids DECREASE GnRH secretion -> DECREASED LH and FSH -> DECREASED endogenous testicular production of androgens." },
  { id: "re5", category: "Hormones", q: "PCOS vs amenorrhea due to anorexia: direction of LH and FSH, and mechanism?", a: "PCOS: select INCREASED LH and DECREASED FSH (INCREASED LH/FSH ratio) - the hirsutism comes from the LH. Anorexia: DECREASED for both LH and FSH. Both are due to decreased/abnormal GnRH pulsation. In PCOS the starting point is insulin resistance in a high-BMI female causing abnormal GnRH pulsation." },
  { id: "re6", category: "Hormones", q: "Which cell types respond to LH vs FSH, in males and females?", a: "LH (produced by anterior pituitary) stimulates testicular LEYDIG cells in males and ovarian THECA INTERNA cells in females to make androgens. FSH stimulates testicular SERTOLI cells and ovarian GRANULOSA cells to make aromatase and inhibin B; in males FSH also facilitates sperm maturation." },
  { id: "re7", category: "Aromatase", q: "What hormones does aromatase convert into which estrogens, and where is it made?", a: "Produced by Sertoli cells in males and granulosa cells in females in response to FSH. Testosterone -> estradiol (potent estrogen). Androstenedione -> estrone (less potent). DHEA-S -> estriol (pregnancy-associated, weakest). Anastrazole and exemestane are aromatase inhibitors." },
  { id: "re8", category: "Aromatase", q: "An NBME question shows gynecomastia in a male and granulosa cell tumor is not an option. What is the answer and the mechanism?", a: "Sertoli-Leydig cell tumor. SL tumors normally make androgens; gynecomastia is possible because of aromatization of androgens into estrogens. Same logic explains physiologic gynecomastia in adolescent males and virginal breast hypertrophy in adolescent females - increased androgens -> aromatization -> increased estrogens. Estrogens also mediate closure of growth plates via aromatization from androgens." },
  { id: "re9", category: "hCG", q: "hCG: source, function, and the reason it rises then falls in early pregnancy?", a: "Produced by syncytiotrophoblastic cells of the placenta; maintains the corpus luteum (remnant of the ruptured follicle) after fertilization. The corpus luteum secretes progesterone to maintain the endometrial lining. Without fertilization there is no hCG, so the corpus luteum degrades -> progesterone falls -> endometrium sloughs = menstruation. hCG peaks at 8-10 weeks, then the placenta takes over progesterone production, obviating the corpus luteum - so hCG falls." },
  { id: "re10", category: "hCG", q: "Why is beta-hCG (not total hCG) measured on a pregnancy test?", a: "hCG shares the same alpha subunit with TSH, LH, and FSH, so the beta subunit must be measured to determine whether hCG is present. High hCG at 8-10 weeks is responsible for the nausea and vomiting of pregnancy; if severe with urinary ketones, it is hyperemesis gravidarum." },
  { id: "re11", category: "hCG", q: "A male patient taking hCG develops gynecomastia. Mechanism?", a: "Testis producing estrogen. hCG shares the same alpha subunit with LH and FSH, so giving hCG is like giving LH and FSH together: LH effect -> androgen production; FSH effect -> aromatase production -> androgens converted to estrogens in the testis -> gynecomastia." },
  { id: "re12", category: "hCG", q: "Second-trimester quad screen: which analyte is elevated in Down syndrome and how do you keep the directions straight?", a: "hCG is INCREASED in Down syndrome (along with inhibin A); AFP and estriol are DECREASED. The ones with H's are up: hCG and inhibin A. Also: pregnancy can occur in Peds before the first menses - a 13-year-old with morning nausea, bloating, and breast tenderness who has never had a period gets serum beta-hCG as the next best step. Always check beta-hCG before starting isotretinoin (teratogenic)." },
  { id: "re13", category: "Estrogens", q: "Estradiol vs estrone vs estriol: main source of each?", a: "Estradiol: mainly the ovaries (and testes in males) - the potent estrogen. Estrone: mainly adipose tissue; in post-menopausal women adipose is the important estrogen source and low BMI increases osteoporosis risk. Estriol: primarily the placenta, DECREASED in Down syndrome. Adrenal DHEA-S can be aromatized into estradiol." },
  { id: "re14", category: "Estrogens", q: "How does the estrogen threshold trigger the LH surge, and what does the surge do?", a: "Estradiol stimulates the endometrial lining to grow during the follicular phase, with levels gradually rising. Once a critical estrogen threshold is reached, estrogen's effect at the hypothalamus flips from NEGATIVE to POSITIVE feedback, causing the LH surge, which triggers rupture of the Graafian follicle (ovulation)." },
  { id: "re15", category: "Estrogens", q: "How does estrogen maintain bone density, and what happens in menopause?", a: "Estrogen maintains bone density by INCREASING the OPG/RANK ratio. In post-menopausal women, decreased estrogen -> INCREASED RANK relative to OPG -> increased osteoclast activity -> osteoporosis. Estrogen also maintains a healthy lipid profile (increases HDL, decreases LDL) and drives female secondary sex characteristics." },
  { id: "re16", category: "Estrogens", q: "HRT: approved indication, and the risks from the absolute increase in estrogen exposure?", a: "HRT is approved only for severe perimenopausal vasomotor symptoms (hot flashes, urge incontinence, atrophic vaginitis) - not for bone density or mood/neurocognition. Increased estrogen exposure increases risk of breast cancer, MI, and thromboembolic events (DVT, PE, stroke) because estrogen upregulates fibrinogen and factors V and VIII." },
  { id: "re17", category: "Estrogens", q: "Which three NBME groups represent unopposed estrogen, and what pathology does it cause?", a: "Unopposed estrogen is the mechanism for endometrial hyperplasia and adenocarcinoma: 1) PCOS, 2) HRT patients who stop taking the progesterone component, 3) granulosa cell tumors. Estrogen stimulates endometrial growth, progesterone inhibits it; the balance keeps the lining in check. Vignette of vaginal bleeding in a woman with unopposed estrogen -> answer is endometrial biopsy." },
  { id: "re18", category: "Progesterone", q: "A graph shows increased body temperature at day 14 of the menstrual cycle. Which hormone is responsible?", a: "Progesterone - it plays a role in thermoregulation and increased secretion at ovulation increases body temperature. Produced by the corpus luteum following ovulation, progesterone maintains the endometrial lining during the luteal phase. If fertilization occurs, hCG maintains the corpus luteum so progesterone production continues." },
  { id: "re19", category: "Progesterone", q: "Why doesn't the pregnant breast lactate, and why are progesterone-only contraceptives safe while breastfeeding?", a: "Progesterone inhibits the effects of prolactin at the alveolar (milk-producing) cells of the breast, preventing lactation during pregnancy. Once the placenta is expelled at parturition and progesterone falls, prolactin can induce lactation. Progesterone-only contraceptives are safe in breastfeeding because the low progesterone does not inhibit lactation; it is the ESTROGEN in combined OCPs that decreases protein content of breast milk." },
  { id: "re20", category: "Prolactin", q: "If the pituitary stalk is severed, which hormone RISES and why?", a: "Prolactin - dopamine inhibits prolactin, and without the stalk there is a lack of negative feedback by dopamine, so prolactin increases. Bromocriptine (D2 receptor agonist) is first-line for prolactinoma; D2 antagonists (antipsychotics, metoclopramide) can cause hyperprolactinemia. Prolactin levels rise during pregnancy but its effects are inhibited by high progesterone." },
  { id: "re21", category: "Oxytocin", q: "Oxytocin: source, stored where, key reflexes, and the risk of excessive administration in labor?", a: "Produced by the hypothalamus and stored in the posterior pituitary; induces milk let-down and uterine contractions. The suckling reflex increases oxytocin secretion (milk let-down; also the love hormone for maternal-neonate bonding). Ferguson reflex: cervical distension by the fetus at parturition increases oxytocin -> increased uterine contractions. Excessive administration during labor can cause uterine hypertonus and tachysystole -> increased risk of uterine rupture and fetal complications." },
  { id: "re22", category: "Inhibin", q: "Inhibin A and B: source and endocrine effect, and which one is in the quad screen?", a: "Both produced by Sertoli cells in males and granulosa cells in females; both exert negative feedback at the anterior pituitary to specifically DECREASE FSH secretion. Inhibin A (not B) is measured in the second-trimester quad screen because it is more accurate for predicting fetal chromosomal abnormalities." },
  { id: "re23", category: "Androgens", q: "5-alpha reductase deficiency: vignette and explanation?", a: "A karyotypic male (46XY) appears phenotypically female for the first 12 years of life, then has penis at age 12: the pubertal testosterone surge overrides the deficiency once a threshold DHT level is reached. Vignette: 12-year-old girl grown 4 inches in 4 months + acne + hair on upper lip + 3-4-cm clitoral hood; karyotype 46XY. DHT is necessary for external male secondary sex characteristics; the enzyme is inhibited by finasteride (BPH, androgenetic alopecia)." },
  { id: "re24", category: "Androgens", q: "Androgen-insensitivity syndrome: classic vignette and hormone levels?", a: "Karyotypic male (46XY) presenting as phenotypic female due to failure of testosterone and DHT to have effect. Testosterone and DHT are normal or ELEVATED due to decreased negative feedback at the hypothalamus and anterior pituitary, so LH is also increased. Vignette: 15-year-old girl who has never had a period + vagina ends in a blind pouch + scanty or absent pubic/axillary hair." },
  { id: "re25", category: "Androgens", q: "High anabolic steroid use: full list of consequences on labs and organs?", a: "Accelerates atherosclerotic plaque maturity (increased LDL and TGAs, decreased HDL), increases plaque calcium scores, increases hematocrit (sometimes hyperviscosity syndrome), suppresses the hypothalamic-gonadal axis (decreased endogenous androgen synthesis and spermatogenesis), and can cause liver damage. Androgens normally build muscle, maintain spermatogenesis, enhance libido, and stimulate prostate growth." },
  { id: "re26", category: "Androgens", q: "What stimulates ABP production, and what does ABP do?", a: "Androgen-binding protein is produced by Sertoli cells in response to TESTOSTERONE (not FSH) and binds androgen locally at the seminiferous tubules to facilitate spermatogenesis. SHBG instead binds and carries androgen and estrogen in the blood - most is bound and the free fraction is most biologically active. Estrogens can increase SHBG; anabolic steroid users sometimes try to decrease SHBG to increase androgen effects." },
  { id: "re27", category: "hPL", q: "Human placental lactogen: source, timing, and effect on glucose?", a: "Produced by syncytiotrophoblastic cells of the placenta (same cells as hCG), highest levels in the 3rd trimester. It increases insulin resistance to increase serum glucose availability for the developing fetus; the biologic tradeoff is increased risk of gestational diabetes for the mother." },
  // ===== REPRO: Menstrual cycle =====
  { id: "re28", category: "Menstrual Cycle", q: "Walk the follicular (proliferative) phase endocrinology from follicle development to ovulation.", a: "Multiple follicles develop, one becomes dominant and the rest degenerate. Granulosa cells in the dominant follicle produce increasing estradiol, thickening the endometrial lining (proliferation). Rising estrogen reaches a critical threshold where its feedback on LH and FSH flips from negative to positive, causing the sharp LH surge. The LH surge triggers ovulation: the Graafian follicle ruptures and forms the corpus luteum. Follicular phase histology shows straight, tubular glands." },
  { id: "re29", category: "Menstrual Cycle", q: "A woman's cycle length changes from 28 days. Which phase changes length, and what is the main hormone of the luteal phase?", a: "The FOLLICULAR phase changes - the luteal (secretory) phase is always 14 days. Progesterone is the main hormone of the luteal phase; secretory phase histology shows coiled and spiral-shaped glands." },
  { id: "re30", category: "Menstrual Cycle", q: "What cells make progesterone vs androgens/estrogens in the corpus luteum?", a: "Granulosa cells of the developing follicle transform into granulosa-LUTEIN cells in the corpus luteum - these secrete progesterone. Theca-interna cells become theca-lutein cells and continue secreting androgens, which granulosa-lutein aromatase converts into estrogens (the secondary, smaller estrogen rise of the luteal phase). If no fertilization, the corpus luteum degenerates -> progesterone falls -> sloughing of the endometrium." },
  { id: "re31", category: "Menstrual Cycle", q: "Why do women with anovulation (e.g., PCOS) have irregular and missed menses?", a: "Menstruation is caused by the presence of progesterone followed by its withdrawal. In anovulation no ovulation occurs, so no corpus luteum forms, so there is no sequence of progesterone present followed by withdrawal. The endometrium never gets its programmed signal, giving irregular menses and missed cycles." },
  // ===== REPRO: Spermatogenesis + Oogenesis =====
  { id: "re32", category: "Spermatogenesis", q: "Walk spermatogenesis from spermatogonia to spermatozoa with ploidy at each step.", a: "Spermatogonia: DIPLOID (2n) - begin mitosis (not meiosis) at puberty, some remain stem cells and some become primary spermatocytes. Primary spermatocytes: DIPLOID - each undergoes meiosis I, yielding two haploid secondary spermatocytes. Secondary spermatocytes: HAPLOID (n) - each undergoes meiosis II, producing four haploid spermatids. Spermatids: HAPLOID - mature into sperm. Spermatozoa: HAPLOID - mature sperm after flagellum (tail) growth." },
  { id: "re33", category: "Oogenesis", q: "Oogenesis: what is the meiotic arrest pattern from fetal life through fertilization?", a: "Oogonia (diploid) undergo mitosis during fetal development forming primary oocytes. Primary oocytes arrest in PROPHASE I before birth (surrounded by granulosa cells as primordial follicles) and stay there until puberty. At puberty, each month a primary oocyte completes meiosis I, yielding a secondary oocyte plus a polar body. The secondary oocyte arrests in METAPHASE II and only completes meiosis II (mature ovum + polar body) if fertilization occurs. That is what forms the diploid zygote." },
  // ===== REPRO: Fertilization + Implantation =====
  { id: "re34", category: "Fertilization", q: "Where does fertilization typically occur, and what are the three structures of the blastocyst?", a: "Typically in the ampulla of the fallopian tube. Zygote (diploid) undergoes cleavage divisions forming the morula (solid ball), which divides further into the blastocyst (hollow ball): 1) outer trophoblast, 2) inner cell mass, 3) central fluid-filled blastocoel." },
  { id: "re35", category: "Fertilization", q: "What three structures does the inner cell mass become, and what does the trophoblast become?", a: "Inner cell mass -> 1) embryonic disc (gives the three germ layers: ectoderm, mesoderm, endoderm), 2) amniotic sac (produces amniotic fluid), 3) yolk sac (early hematopoiesis and structural support - the human yolk sac contains no yolk). Trophoblast -> the fetal component of the placenta, comprising inner cytotrophoblast and outer syncytiotrophoblast." },
  { id: "re36", category: "Implantation", q: "List the four main functions of the syncytiotrophoblast after implantation.", a: "1) Grows chorionic villi containing fetal blood vessels - the maternal-fetal circulation interface. 2) Grows the chorion (thick membrane surrounding the embryo). 3) Protects the fetus from the mother's immune system. 4) Produces hCG. After implantation the embryo sits between an inner thin amnion (from the inner cell mass) and a thick outer chorion (from syncytiotrophoblast). The endometrial tissue connected to the implanted embryo is the decidua, which contains maternal vessels and enables nutrient and gas exchange." },
  // ===== REPRO: Twinning =====
  { id: "re37", category: "Twinning", q: "An NBME question says there is a THICK dividing membrane between twin fetuses. What is the twinning type and the timing?", a: "Dichorionic/diamniotic twins - monozygotic with the conceptus splitting ~1-3 days post-fertilization (or dizygotic fraternal twins). Number of chorions equals number of placentas, so Di-Di twins have two placentas." },
  { id: "re38", category: "Twinning", q: "Match split timing to monozygotic twin type: 1-3 days, 4-8 days, 8-13 days, 13+ days.", a: "~1-3 days: dichorionic/diamniotic. ~4-8 days: monochorionic/diamniotic (no thick dividing membrane since they share a chorion). ~8-13 days: monochorionic/monoamniotic - high risk of twin-twin transfusion syndrome due to entanglement of fetal vessels. ~13 days or later: conjoined twins." },
  // ===== REPRO: Embryology =====
  { id: "re39", category: "Development by Week", q: "Embryology by week: what happens in weeks 1, 2, 3, and 4, and when is the fetus most susceptible to teratogens?", a: "Week 1: fertilization + zygote divides into the morula. Week 2: morula becomes a blastocyst and implants into the endometrium. Week 3: neural plate forms, primitive germ layers appear, and the neural tube begins to form; folic acid (B9) is most important in the first 3-4 weeks, and deficiency gives neural tube defects like spina bifida. Week 4: neural tube continues, heart (4 chambers) and limbs begin to form. The fetus is most susceptible to teratogens at 3-8 weeks (organogenesis is week 5 onward)." },
  { id: "re40", category: "Germ Layers", q: "Ectoderm vs neural crest: derivatives and the classic associated tumors?", a: "Ectoderm (derived from clefts aka grooves): CNS, PNS, skin, hair, nails, lens of eye. Craniopharyngioma comes from Rathke pouch ('roof of the primitive oral cavity/oropharynx'; surface ectoderm). Neural crest (specialized ectoderm from the neural plate): melanocytes, PNS, adrenal medulla, various cardiac structures; pheochromocytoma, neuroblastoma, and medulloblastoma are neural crest-derived. Neural crest is the classic answer for Hirschsprung (failure of distal neural crest migration in the GIT) and fetal alcohol syndrome (cardiac defects)." },
  { id: "re41", category: "Germ Layers", q: "Mesoderm vs endoderm: derivative lists and the classic NBME swaps?", a: "Mesoderm (derived from arches): most bones, muscles, cartilage, blood vessels, heart. Endoderm (derived from pouches): GIT, lungs, thymus, thyroid, parathyroids. NBME has given tracheoesophageal fistula and asked the embryology of the esophageal atresia -> answer ENDODERM. Thyroglossal duct cyst embryo answer -> endoderm of foramen cecum." },
  { id: "re42", category: "Pharyngeal Pouches", q: "A patient is missing a superior parathyroid gland. Which pouch failed?", a: "The 4TH pouch. The 3rd pouch becomes the two INFERIOR parathyroids + thymus; the 4th pouch becomes the two SUPERIOR parathyroids. These also show up in DiGeorge syndrome questions, and they can flip it: adenoma of an inferior parathyroid -> 3rd pouch." },
  { id: "re43", category: "Development", q: "A hysterosalpingogram shows uterine didelphys or bicornuate uterus. What is the embryologic defect?", a: "Failure of paramesonephric (Mullerian) ducts to fuse. The Mullerian ducts give rise to the fallopian tubes, uterus, cervix, and upper vagina." },
  { id: "re44", category: "Development", q: "Wolffian (mesonephric) ducts: what do they form and what drives their development?", a: "Epididymis (sperm storage/maturation), vas deferens (ductus deferens), seminal vesicles, and ejaculatory ducts. Development is stimulated by testosterone." },
  { id: "re45", category: "Development", q: "MIF and TDF: who makes each, when, and what do they cause?", a: "MIF (Mullerian-inhibitory factor) is produced by Sertoli cells starting around 8 weeks' gestation in males; it causes regression of the Mullerian (paramesonephric) ducts, preventing female structures. TDF (testis-determining factor, SRY protein, coded by the SRY gene on the Y chromosome, secreted by the gonadal ridge) initiates development of testes. Sequence: SRY -> testes; Sertoli MIF -> Mullerian regression; Leydig testosterone -> Wolffian development. Females develop Mullerian ducts in the absence of MIF." },
  { id: "re46", category: "Development", q: "Male-female equivalent structures: scrotum, labia minora, prostate, Bartholin glands, glans penis - what are the homologs?", a: "Labioscrotal swelling: scrotum (male) = labia majora (female). Urogenital folds: ventral shaft of penis/penile urethra = labia minora. Urogenital sinus: prostate gland = glands of Skene; Cowper glands = Bartholin glands. Genital tubercle: corpus cavernosum/spongiosum = vestibular bulbs; glans penis = glans clitoris." },
  // ===== REPRO: Fetal circulation =====
  { id: "re47", category: "Fetal Circulation", q: "Umbilical vein vs umbilical arteries: direction of blood and post-birth remnants?", a: "Umbilical vein: carries oxygenated blood from mother to fetus; post-birth remnant is the ligamentum teres hepatis (round ligament of the liver). Umbilical arteries (two, vs one vein): carry deoxygenated blood from fetus back to the mother; remnants are the MEDIAL umbilical ligaments - do not confuse with the MEDIAN umbilical ligament, the remnant of the fetal urachus (which connects fetal bladder to umbilicus). Wharton jelly is the specialized connective tissue protecting the cord vessels." },
  { id: "re48", category: "Fetal Circulation", q: "Velamentous cord insertion: what is it and why is it risky?", a: "A rare condition where the umbilical cord inserts into the fetal membranes rather than directly into the placenta, exposing umbilical vessels and risking injury where they are not protected by Wharton jelly." },
  { id: "re49", category: "Fetal Circulation", q: "Ductus arteriosus: connect what to what, why, closure timing, remnant, and the classic murmur?", a: "Connects the pulmonary trunk to the proximal descending aortic arch, allowing most oxygenated blood from the fetal RV to bypass the high-resistance nonfunctional fetal lungs into systemic circulation. Closes within the first week post-birth; remnant = ligamentum arteriosum. PDA = failure of closure; in the neonate blood reverses (aortic arch back to pulmonary trunk) causing a continuous, machinery-like murmur (pan-systolic-pan-diastolic, to-and-fro). PDA is classically seen in congenital rubella syndrome; the NBME answer is extra-cardiac left-to-right shunt." },
  { id: "re50", category: "Fetal Circulation", q: "Ductus venosus and foramen ovale: purpose and post-birth remnants?", a: "Ductus venosus connects the umbilical vein to the fetal IVC, letting oxygenated placental blood bypass the high-resistance fetal liver straight to the fetal RA; remnant = ligamentum venosum. Foramen ovale is the opening in the fetal inter-atrial septum allowing oxygenated RA blood into the LA, bypassing the fetal lungs; remnant = fossa ovalis. Failure of closure gives a patent foramen ovale, a type of ASD in the neonate (fixed splitting of S2)." },
  // ===== REPRO: Gyn anatomy =====
  { id: "re51", category: "Gyn Ligaments", q: "Broad ligament: three peritoneal layers and what it contains?", a: "Connects the uterus, fallopian tubes, and ovaries to the lateral pelvic walls; contains the uterine arteries and veins. Three layers: mesosalpinx (upper fold enclosing the fallopian tube), mesometrium (supports the uterus, largest part), mesovarium (fold surrounding the ovary)." },
  { id: "re52", category: "Gyn Ligaments", q: "Which ligament contains the ovarian artery and vein versus the uterine artery and vein?", a: "SUSPENSORY ligament (ovary to pelvic side wall) contains the ovarian artery and vein. Cardinal ligament (cervix to pelvic side wall) contains parts of the uterine artery and vein. Ovarian ligament connects ovary to uterus. Round ligament connects the uterine horn to the labia majora. Uterosacral ligament connects posterior cervix/uterus to the sacrum." },
  { id: "re53", category: "Gyn Ligaments", q: "Water under the bridge: what does it mean and where does the ureter get injured?", a: "The uterine artery bridges over the ureter as it courses through the pelvis - water (ureter) under the bridge (uterine artery). During gynecologic surgeries, especially hysterectomy, the ureter is prone to damage. Also: an NBME question described a fetus seen on ultrasound in the PARAMETRIUM of the uterus - parametrium is connective tissue (not a ligament) connecting the broad ligament to the pelvic side wall, and the answer was ectopic pregnancy." },
  { id: "re54", category: "Gyn Vasculature", q: "Arterial supply, venous drainage, and lymphatics of the uterus vs ovaries?", a: "Uterus: uterine arteries (branch off internal iliacs); drained by uterine veins into internal iliac veins; lymph to external and internal iliac nodes. Ovaries: ovarian arteries branch directly off the abdominal aorta at L2; drained by ovarian veins into the IVC on the right (right to IVC) and the left renal vein on the left; lymph drains to PARA-AORTIC nodes." },
  { id: "re55", category: "Pelvic Floor", q: "USMLE asks which muscle is NOT strengthened by Kegel exercises. Answer?", a: "The internal anal sphincter. Internal sphincters of the anus and bladder are under autonomic (sympathetic) control, not somatic/voluntary - you cannot exercise them. The external anal and bladder sphincters are under voluntary control." },
  { id: "re56", category: "Pelvic Floor", q: "During a posterior midline episiotomy, what structure will the doctor cut into if the cut goes too far?", a: "The external anal sphincter. An episiotomy is performed before Stage 2 of labor (delivery of the fetus) to cut the vagina posteriorly in the midline, preventing laceration during delivery of a macrosomic fetus." },
  { id: "re57", category: "Perineal Nerves", q: "Erection, emission, ejaculation: the three nerves?", a: "Erection: pelvic splanchnic nerves (parasympathetic) from S2-S4 - 2,3,4 keeps the penis off the floor. Emission: hypogastric nerves (sympathetic) from L1-L2. Ejaculation: pudendal nerve (somatic, voluntary) from S2-S4." },
  { id: "re58", category: "Perineal Nerves", q: "Pudendal nerve: its three USMLE functions?", a: "1) Main sensory nerve of the perineum and external genitalia (penis, scrotum, clitoris, labia) - that sensory aspect facilitates erection but pelvic splanchnics actually mediate it. 2) Main motor nerve of pelvic floor muscles (external anal sphincter, levator ani) for Kegel exercises. 3) Target of the pudendal nerve block during parturition for episiotomy. Also: sildenafil (PDE-5 inhibitor) acts on smooth muscle cells within small blood vessels inside the erectile tissue - the erectile muscle on a penis cross-section - not the dorsal artery." },
  { id: "re59", category: "Penis", q: "Hypospadias vs epispadias vs phimosis vs paraphimosis?", a: "Hypospadias: urethral meatus opens on the underside (ventral) of the penis. Epispadias: meatus opens on top (dorsal). Phimosis: cannot retract the prepuce (foreskin) over the glans. Paraphimosis: prepuce retracted but cannot be replaced back over the glans - the emergency." },
  { id: "re60", category: "Male Pathology", q: "Cryptorchidism: two major risks, management timing, and the classic NBME adult vignette?", a: "Undescended testis. Risks: infertility (increased intra-abdominal temperature decreases spermatogenesis) and testicular carcinoma. No treatment before age 6 months; after 6 months, orchidopexy. NBME vignette: adult with a groin mass and no testicle palpable in one hemiscrotum -> the groin mass is testicular carcinoma." },
  { id: "re61", category: "Male Pathology", q: "Testicular torsion: cause, signs, next best step?", a: "Acutely painful testis, medical emergency, can cause ischemia and loss of the testis. Abnormality of the gubernaculum leads to bell-clapper deformity and increased rotation risk. Negative Prehn sign (no pain relief when elevating the scrotum) and negative cremasteric reflex (no scrotal retraction with inner-thigh stroking) point to torsion. Next best step: Doppler ultrasonography, then surgery." },
  { id: "re62", category: "Male Pathology", q: "Epididymitis vs torsion of appendix testis vs orchitis?", a: "Epididymitis: (+) Prehn and (+) cremasteric reflex; chlamydia and gonorrhea under 35, E. coli over 35 (same organisms as prostatitis). Torsion of appendix testis: painful pediatric testis with blue superior pole (blue dot sign) and INTACT cremasteric reflex - not the same as testis torsion. Orchitis: inflammation of the testis; mumps is the classic HY cause (unvaccinated), otherwise the bacterial causes mirror epididymitis/prostatitis by age." },
  { id: "re63", category: "Male Pathology", q: "Peyronie disease and priapism: what are they and how is priapism treated?", a: "Peyronie: curvature deformity of the penis from fibrous plaque within the tunica albuginea; treatment only if functional impairment. Priapism: erection over 4 hours; caused by sickle cell or PDE-5 inhibitors (tadalafil/sildenafil); treatment is injection of an alpha-1 agonist (phenylephrine) into the erectile tissue to constrict blood vessels and decrease flow." },
  { id: "re64", category: "Male Pathology", q: "What is a hydrocele and its embryologic connection to indirect inguinal hernia?", a: "Serous fluid collection in the scrotum between layers of the tunica vaginalis around the testis; mechanism is patent processus vaginalis. The processus vaginalis is an embryonic outpouching of peritoneum that descends into the scrotum and normally obliterates shortly after birth; if it stays open it can cause a hydrocele or an indirect inguinal hernia." },
  // ===== REPRO: Scrotal + male anatomy extras =====
  { id: "re65", category: "Male Pathology", q: "Hydrocele vs spermatocele vs varicocele on exam?", a: "Hydrocele: serous fluid collection from patent processus vaginalis, common in neonates, TRANSILLUMINATES, no treatment before age 1 (most close spontaneously). Spermatocele: obscure serous fluid containing sperm within the epididymis, usually adult men, also transilluminates. Varicocele: dilation of pampiniform venous plexus, does NOT transilluminate, buzzy 'bag of worms,' heavy dragging left-sided scrotum. Almost always left-sided because the left testicular vein drains at a 90-degree angle into the left renal vein (left testicular vein -> left renal vein -> IVC, versus right testicular vein -> IVC direct); can occur from left renal vein thrombosis in nephrotic syndrome (loss of antithrombin III -> hypercoagulable)." },
  { id: "re66", category: "Male Pathology", q: "Hernia through the spermatic cord: where do abdominal contents herniate, and what embryonic structure is involved?", a: "Indirect inguinal hernia: abdominal contents herniate medial to the inferior epigastric vessels through the internal inguinal ring within the spermatic cord. Embryology: patent processus vaginalis (the outpouching of peritoneum that descends with the testis and normally obliterates after birth) - same lesion as hydrocele." },
  { id: "re67", category: "Male Pathology", q: "A man has recurrent pulmonary infections and azoospermia on a semen sample. Two possible classic diagnoses?", a: "Cystic fibrosis if sperm are ABSENT: congenital bilateral absence of the vas deferens (CBAVD) is seen in CF. Kartagener (primary ciliary dyskinesia) if sperm are PRESENT but poorly motile: the vas deferens is intact but ciliary dysfunction impairs motility. In women with PCD there can be ectopic pregnancy from impaired fallopian tube cilia." },
  // ===== REPRO: Birth defects =====
  { id: "re68", category: "Birth Defects", q: "Cleft lip vs cleft palate: embryology and recurrence numbers?", a: "Cleft lip: failure of fusion of the maxillary and nasal prominences. Cleft palate: failure of fusion of the lateral palatine processes (palatal shelves). Polygenic, 1 in 1,000-5,000; on USMLE the cause is a one-off developmental anomaly (like pyloric stenosis and ASD/VSD - usually not syndromic). If a couple has a child with it, the chance of a second affected child is 3-5%; if one parent is affected, 10-15% for any child." },
  { id: "re69", category: "Birth Defects", q: "Malformation vs deformation vs disruption, with examples?", a: "Malformation: intrinsic abnormality of an organ from genetic factors or early environmental influences (teratogens) - spina bifida, cleft lip/palate, congenital heart defects, phocomelia (thalidomide). Deformation: a normally-formed part becomes abnormally shaped later, usually from mechanical forces like uterine compression or oligohydramnios - club foot, congenital hip dysplasia, plagiocephaly. Disruption: a normal part is interrupted by a destructive event - amniotic band syndrome, where fibrous amniotic bands entangle a fetal limb and cause amputation." },
  { id: "re70", category: "Incontinence", q: "Stress incontinence: vignette buzzwords and management?", a: "Loss of urine with INCREASED intra-abdominal pressure - laughing, sneezing, coughing. Classic risk factor grand multiparity with weakened pelvic floor (about half of vignettes are idiopathic). Buzzwords: downward mobility of the vesicourethral junction, urethral hypermobility, urethral atrophy with loss of urethrovesical angle. Tx is Kegel exercises (strengthen levator ani, pubococcygeus, external urethral sphincter); no medications; mid-urethral sling if Kegels fail." },
  { id: "re71", category: "Incontinence", q: "Urge incontinence: mechanism, buzzword, classic associations, treatment?", a: "Detrusor hyperactivity/instability. NBME will literally use the word URGE - voiding 6-12+ times daily unrelated to sneezing/coughing/laughing. Vignette can mention urge to void when stepping out of the car or putting the key in the front door. Ultra-HY association: multiple sclerosis (MS shows up as URGE, never overflow). Tx: oxybutynin (muscarinic receptor antagonist) - decreases detrusor activity. A patient with dysuria + urgency after a urinary catheter is UTI, not detrusor hyperactivity." },
  { id: "re72", category: "Incontinence", q: "Overflow incontinence: two causes, the lab clue, and the drugs for each?", a: "BPH or diabetes. INCREASED post-void volume (normal <50 mL; they give 300-400 mL). BPH: old man + high creatinine (post-renal azotemia) -> insert catheter, then treat with finasteride (5-alpha reductase inhibitor) or an alpha-1 blocker (tamsulosin, terazosin). Diabetes: neuropathic hypotonic/neurogenic bladder -> give bethanechol (muscarinic receptor agonist) to stimulate the detrusor. Know oxybutynin vs bethanechol cold - pass-level. Spinal trauma, spinal metastases, and cauda equina can also cause retention with overflow." },
  // ===== REPRO: Moles =====
  { id: "re73", category: "Hydatidiform Moles", q: "A 16-week pregnant woman has fundal height at the umbilicus (normal at 20 weeks) and beta-hCG in the hundreds of thousands. What is this and what else can it mimic?", a: "Hydatidiform mole - a nonviable pregnancy with abnormal trophoblastic proliferation, part of gestational trophoblastic disease (GTD), which also encompasses choriocarcinoma. Uterus much larger than gestational age with super-elevated beta-hCG. Can mimic preeclampsia: hypertension and proteinuria at UNDER 20 weeks' gestation = mole until proven otherwise (preeclampsia is an over-20-weeks disease)." },
  { id: "re74", category: "Hydatidiform Moles", q: "Complete vs partial mole: fertilization event, karyotype, findings, and treatment?", a: "Complete: empty egg fertilized by a single sperm that duplicates its DNA - karyotype usually 46XX (46YY incompatible). Snowstorm appearance on ultrasound, bunches of grapes on gross path, NO fetal parts. Partial: normal egg fertilized by two sperm - 69XXX, 69XXY, or 69XYY - fetal parts ARE present. Both carry high risk of invasive mole and choriocarcinoma, but if forced to choose, complete carries the higher risk. Tx: surgical evacuation by D&C or suction curettage." },
  { id: "re75", category: "Hydatidiform Moles", q: "Invasive mole vs choriocarcinoma?", a: "Invasive mole: molar tissue penetrates into the myometrium; potential for metastasis and progression to choriocarcinoma; gross path STILL shows chorionic villi. Choriocarcinoma: cancer of syncytiotrophoblastic tissue, usually arising from a mole; super-elevated beta-hCG; loves lung and brain metastases (woman with ultra-high beta-hCG + pulmonary nodules or stroke-like presentation = choriocarcinoma); gross path is a bloody mess with NO chorionic villi." },
  // ===== REPRO: Ovarian neoplasms =====
  { id: "re76", category: "Ovarian Cancer", q: "Ovarian serous vs mucinous tumors, benign vs malignant forms?", a: "Serous cystadenoma: benign, fallopian tube-like epithelium, can be bilateral, can have psammoma bodies. Serous cystadenocarcinoma: malignant, 20-30% bilateral at diagnosis. Mucinous cystadenoma: benign, intestine-like epithelium, loculated (tiny cavities, honeycomb). Mucinous cystadenocarcinoma: malignant, can cause pseudomyxoma peritonei (mucin-producing cells and gelatinous ascites in the peritoneal cavity)." },
  { id: "re77", category: "Ovarian Cancer", q: "Dysgerminoma: the three facts that make it the seminoma equivalent?", a: "Large uniform cells with clear cytoplasm (same as seminoma); highly sensitive to chemo- and radiotherapy (same as seminoma); LDH is the tumor marker. Can occur idiopathically or in Turner syndrome." },
  { id: "re78", category: "Ovarian Cancer", q: "Female with an ovarian neoplasm + thickened endometrial stripe + vaginal bleeding. Diagnosis and mechanism?", a: "Granulosa cell tumor - it produces estrogen, which causes endometrial hyperplasia and increases risk of endometrial cancer through unopposed estrogen. (No corpus luteum means no progesterone to balance it.)" },
  { id: "re79", category: "Ovarian Cancer", q: "The AFP versus hCG pearl for ovarian germ cell tumors?", a: "Yolk sac tumor (endodermal sinus tumor): the USMLE answer for ovarian tumor in pediatrics (up to about age 3), secretes AFP, Schiller-Duval bodies on histology. Embryonal carcinoma: aggressive and anaplastic, secretes BOTH AFP and hCG together, usually adult men. Rule: only AFP high = yolk sac; AFP and hCG high = embryonal carcinoma." },
  { id: "re80", category: "Ovarian Cancer", q: "Brenner tumor, struma ovarii, Krukenberg tumor?", a: "Brenner: benign ovarian tumor with bladder-like epithelium - histology shows urothelium (transitional cells); can appear tan/yellow grossly. Struma ovarii: benign ovarian tumor that secretes thyroid hormone. Krukenberg: gastric metastases to BOTH ovaries, with mucin-containing signet-ring cells on biopsy; spread from stomach is usually hematogenous." },
  // ===== REPRO: Endometrial cancer + fibroids =====
  { id: "re81", category: "Endometrial Cancer", q: "What drives endometrial cancer in PCOS/anovulation?", a: "Unopposed estrogen. Estrogen stimulates endometrial growth while progesterone prevents overgrowth. In anovulation/PCOS no ovulation means no corpus luteum (the follicular remnant), so no progesterone is made to balance estrogen -> endometrial hyperplasia -> increased endometrial adenocarcinoma risk. A perimenopausal overweight woman with breakthrough bleeding or ANY post-menopausal bleeding -> endometrial biopsy." },
  { id: "re82", category: "Endometrial Cancer", q: "Beyond PCOS, what other causes of unopposed estrogen lead to endometrial cancer, and the hereditary association?", a: "Granulosa cell tumor of the ovary (rare), and HRT patients who stop taking the progesterone component. Also associated with HNPCC (Lynch syndrome)." },
  { id: "re83", category: "Fibroids", q: "Fibroids: what are they pathologically and what does the USMLE want done incidentally?", a: "Leiomyomata uteri - most common benign tumor in women, smooth muscle tumors of the myometrium. Stain desmin positive; grossly white with whorled structure. Found incidentally on ultrasound or autopsy -> OBSERVE / follow-up; they are not managed almost always, and there is negligible progression risk to leiomyosarcoma. Do not pick myomectomy for an incidental fibroid." },
  // ===== REPRO: Vulvovaginal lesions =====
  { id: "re84", category: "Vulvovaginal", q: "Vulvovaginal carcinoma, condylomata acuminata, lichen sclerosus: key facts?", a: "Vulvovaginal carcinoma: almost always squamous cell carcinoma from HPV 16 or 18; rarely from lichen sclerosus. Condylomata acuminata: warts from HPV 6/11 - painless skin-colored cauliflower papules. Lichen sclerosus: whitish-grey rough parchment-like patch in a woman over 50, from chronic irritation and autoimmunity (NOT HPV); histology shows atrophy, hyperkeratosis, and a band of lymphocytes in the dermis; next best step is biopsy to rule out SCC, then topical steroid if negative." },
  { id: "re85", category: "Vulvovaginal", q: "Bunches of grapes protruding from the vagina of a small child. Diagnosis?", a: "Sarcoma botryoides - rhabdomyosarcoma of the vagina seen in pediatrics. (Compare with clear cell vaginal adenocarcinoma: DES exposure in the patient's mother while pregnant 30-50 years ago, in women 30s-50s.)" },
  { id: "re86", category: "Vulvovaginal", q: "A tender bump at the 4- or 8-o'clock position of the vulva: diagnosis, organism, management?", a: "Bartholin gland cyst; if warm and red (infected), Bartholin gland abscess. Organism answer: POLYMICROBIAL. Cysts get sitz bath + warm compresses; overt abscesses get drainage. Also: a child with foul-smelling vaginal discharge and no trauma = vaginal foreign body; discharge with lacerations = sexual abuse." },
  // ===== REPRO: Breast neoplasia =====
  { id: "re87", category: "Breast", q: "DCIS vs invasive ductal carcinoma vs lobular carcinoma in situ?", a: "DCIS: most common malignant breast cancer, in situ means confined superficial to the basement membrane; MICROCALCIFICATIONS on mammography = DCIS until proven otherwise; Paget disease of the breast (nipple eczema over 50) is often the skin extension of underlying DCIS. Invasive ductal: invasive form with stellate morphology on biopsy. Lobular carcinoma in situ: malignant potential but confined superficial to basement membrane and commonly BILATERAL - if a question mentions bilateral breast cancer, think lobular until proven otherwise (unless microcalcifications or stellate morphology are mentioned, which say ductal). Medullary and comedo carcinomas are the named distractors." },
  { id: "re88", category: "Breast", q: "A rubbery, mobile, non-tender lump in a woman in her 20s-40s. Next step and disposition?", a: "Fibroadenoma - the most common breast tumor overall, benign. On ultrasound it is a solid mass WITHOUT calcification (calcifications would argue ductal carcinoma). FNA is the next best step to confirm; confirmed fibroadenomas do not need excision. Compare cystosarcoma phyllodes: fast-growing leaf-like lesion on microscopy, benign or malignant based on histology." },
  { id: "re89", category: "Breast", q: "BRCA1/2: gene type, inheritance pattern, and the broken molecular process?", a: "Tumor suppressor genes inherited in an AUTOSOMAL DOMINANT fashion with incomplete penetrance (can skip a generation - NBME asks a pedigree). The messed-up molecular process is RECOMBINATIONAL DOUBLE-STRANDED DNA repair." },
  { id: "re90", category: "Breast", q: "ER/PR vs HER2/neu vs triple-negative breast cancer: prognosis and targeted drugs?", a: "ER/PR positivity correlates with BETTER prognosis, partly because SERMs and aromatase inhibitors can be used. HER2/neu positivity is WORSE; trastuzumab (Herceptin) targets it. Triple-negative ER/PR/HER2 has the worst prognosis due to increased aggressiveness, recurrence, and metastasis to lungs/brain. HRT increases breast cancer risk (and thromboembolism/MI/stroke via fibrinogen and factors V/VIII) - separate from unopposed estrogen, which is the endometrial cancer risk factor and is avoided as long as the progesterone component is taken." },
  { id: "re91", category: "Breast", q: "Fibrocystic change: the three ways it shows up and why you do nothing?", a: "Benign cystic alteration in women 20s-50s. NBME presentations: 1) classic - woman 20s-30s with bilateral waxing/waning breast tenderness over the menstrual cycle; 2) UNILATERAL tenderness or sharp pain in one breast (it is not always bilateral); 3) painless unilateral cyst draining brown/greenish fluid in a woman in her 40s. It is a clinical diagnosis - no biopsy or ultrasound - and treatment is symptomatic only (warm showers, evening primrose oil). Biopsy buzzwords occasionally mentioned: sclerosing adenosis, apocrine metaplasia, blue dome cysts." },
  { id: "re92", category: "Breast", q: "Simple vs complex breast cyst: what they mean on ultrasound and what to do?", a: "Simple means hypoechoic (black), a fluid-filled cyst: observed without FNA unless causing discomfort. Complex means at least partly hyperechoic (white), meaning a solid component: all complex cysts require FNA biopsy. Watch out: sudden growth, e.g., a new simple cyst appearing months after starting HRT, is an indication for BIOPSY of the lesion." },
  { id: "re93", category: "Breast", q: "Mastitis vs breast abscess vs galactocele?", a: "Mastitis: S. aureus usually; red cracked fissured nipple in a breastfeeding woman OR a red, warm, tender NON-FLUCTUANT mass. Treat with oral dicloxacillin and CONTINUE breastfeeding through the affected breast (no harm to the neonate; first-gen cephalosporins like cephalexin are equivalent). Abscess: warm red tender FLUCTUANT mass -> drain. Galactocele: milk retention cyst from blocked lactiferous ducts in a recently breastfeeding woman - peri-areolar fluctuant mass that is NOT warm/red and the patient is afebrile; warm compresses then drainage." },
  { id: "re94", category: "Breast", q: "Ductal ectasia, virginal breast hypertrophy, gynecomastia, fat necrosis?", a: "Ductal ectasia: dilation of lactiferous ducts - diagnosis of exclusion, presents 2/3 of the time as an inverted nipple or 1/3 as biopsy showing dilation of the ducts. Virginal breast hypertrophy: benign asymmetric breast growth in a young woman (8-16, unilateral lump under the nipple); follow-up/observe even if a first-degree relative had breast cancer. Gynecomastia: physiologic in teenage boys (observe); otherwise from increased estrogen in liver failure or drugs (cimetidine, spironolactone, ketoconazole, marijuana); estrogen-mediated, NOT prolactin. Fat necrosis of the breast: non-enzymatic trauma-related necrosis that can calcify (softball hit, tight sports bra) - not the enzymatic fat necrosis of pancreatitis." },
  // ===== REPRO: Ovarian conditions =====
  { id: "re95", category: "Ovarian Cysts", q: "Ruptured ovarian cyst vs adnexal/ovarian torsion?", a: "Ruptured cyst: sudden sharp adnexal pain (adnexa = fallopian tube + ovary), 10-15 mL serosanguineous fluid in the pouch of Douglas on culdocentesis, NO mass; symptomatic NSAID treatment, no laparoscopy. Torsion: intermittent adnexal pain becoming constant over hours to weeks (or a few-hour constant pain), LARGE adnexal mass (e.g., 8 x 12 cm), NO pouch of Douglas fluid; laparoscopic detorsion. Biggest risk factor is a pre-existing anatomic abnormality like a cyst - history of cyst plus large painful mass = torsion." },
  { id: "re96", category: "Ovarian Cysts", q: "The three named ovarian cysts: theca-lutein vs endometrioid vs dermoid?", a: "Theca-lutein: arises from theca cells, usually bilateral, associated with very high hCG states (moles, multiple gestation, fertility drugs); can bleed - hemorrhagic theca-lutein cyst is a diagnosis of exclusion when there is no dysmenorrhea/endometriosis evidence. Endometrioid cyst: aka endometrioma or chocolate cyst - endometrial tissue that bleeds, seen in endometriosis. Dermoid cyst: mature cystic teratoma containing multiple germ layers (hair, skin, teeth); can calcify." },
  // ===== REPRO: Testicular cancer =====
  { id: "re97", category: "Testicular Cancer", q: "Testicular tumors: seminoma vs yolk sac vs embryonal carcinoma, and their markers?", a: "Seminoma: most common testicular cancer in males teenage years and beyond; large uniform cells with watery cytoplasm; chemo- and radiosensitive; placental ALP can be the marker. Yolk sac tumor (endodermal sinus tumor): most common in kids under 3; AFP marker. Embryonal carcinoma: immature/anaplastic cells, usually adult men; combined AFP and hCG markers." },
  { id: "re98", category: "Testicular Cancer", q: "Testicular Sertoli-Leydig, granulosa, and choriocarcinoma tumors?", a: "Sertoli-Leydig: secretes ANDROGENS; can cause gynecomastia on the NBME because increased androgens are aromatized to estrogens. Granulosa cell tumor: secretes estrogen and can also cause gynecomastia (they will not list both SL and granulosa in the same question). Choriocarcinoma: composed of syncytiotrophoblastic placental cells, can occur in males at 20s-30s, and has ELEVATED hCG as the tumor marker." },
  // ===== REPRO: Prostate =====
  { id: "re99", category: "Prostate", q: "Prostate cancer: pathology, the classic metastasis, and the two spine-lesion scenarios?", a: "Adenocarcinoma - the most common cancer in men, stimulated by DHT. Highest yield: OSTEOBLASTIC metastases. Random man over 50 with sudden neurologic leg symptoms and two blastic spine lesions on MRI: if neuro symptoms are present give IV methylprednisolone; if NO neuro symptoms and just vertebral blastic lesions, answer is radiotherapy (morphine + steroids as first move is wrong). Orchiectomy decreases androgen production causing cancer-cell atrophy; flutamide (androgen-receptor blocker) is given BEFORE continuous leuprolide (GnRH agonist causing receptor desensitization) to blunt the early LH/FSH rise. PSA often elevated with free-PSA LOW versus bound; Gleason scoring grades it; parasympathetic erection nerves are at greatest risk in radical prostatectomy." },
  { id: "re100", category: "Prostate", q: "BPH: cause, classic vignette, and the drug class to discontinue?", a: "All older men have enlarged prostates from lifetime DHT exposure. Presents as dribbling, hesitation commencing urination, or interrupted stream in a man 70s+: 'old dude + high creatinine = BPH till proven otherwise.' Discontinue anticholinergic meds first - three classes: 1) first-gen H1 blockers (diphenhydramine, chlorpheniramine), 2) TCAs (amitriptyline), 3) antipsychotics. Prostate may feel nodular; PSA often elevated with free-PSA HIGH (opposite of cancer). Tx: alpha-1 blocker (tamsulosin, terazosin) or finasteride (5-alpha-reductase inhibitor); TURP if refractory." },
  // ===== REPRO: STDs =====
  { id: "re101", category: "HPV", q: "HPV: what do types 6/11 versus 16/18 cause, including the neonatal pearl?", a: "HPV 6/11 cause condylomata acuminata (warts) - and laryngeal papillomatosis in neonates (warts on the vocal cords, asked on NBME). HPV 16/18 cause squamous cell carcinoma of the genitalia/anus; risk is increased in immunocompromised patients (HIV in MSM) and heavy smoking." },
  { id: "re102", category: "Chlamydia", q: "Chlamydia trachomatis: discharge microscopy, complications, drugs, pregnancy rule?", a: "Serovars D-K cause the regular STD: mucopurulent discharge that can advance to PID (fallopian tube scarring -> increased ectopic pregnancy risk). It is obligate intracellular, so discharge shows WBCs with NO organisms on light microscopy - pass-level clue. Tx: one-off stat oral azithromycin (GI disturbance) or a week of doxycycline BID (cannot take with dairy/divalent cations, photosensitivity, slightly more efficacious); doxycycline is OUT in pregnancy because it discolors fetal teeth - pick azithromycin (or erythromycin). Chlamydia also causes reactive arthritis (urethritis, arthritis, eye-itis). Serovars A-C cause trachoma (blindness in Africa); L1-3 cause lymphogranuloma venereum (anal strictures)." },
  { id: "re103", category: "Gonorrhea", q: "Neisseria gonorrhea: microscopy, treatment rule, and the two arthritis presentations?", a: "Mucopurulent discharge same as chlamydia; GRAM-NEGATIVE DIPLOCOCCI on light microscopy; can also advance to PID with increased ectopic risk. Treatment is IM ceftriaxone AND ALWAYS cotreat for chlamydia (oral azithromycin or doxycycline) because chlamydia cannot be ruled out by microscopy - PID after proper-looking ceftriaxone treatment has been answered as 'improper antibiotic treatment' when azithromycin cotreatment was skipped. It does not cause reactive arthritis; it causes gonococcal arthritis presenting as 1) monoarthritis of the knee or 2) triad of mono/polyarthritis + cutaneous papules/pustules + tenosynovitis (deQuervain tenosynovitis stems)." },
  // ===== REPRO: More STDs =====
  { id: "re104", category: "STDs", q: "Vaginal discharge DDx: trichomoniasis vs bacterial vaginosis vs candidiasis?", a: "Trichomonas vaginalis: flagellated protozoan on wet mount; yellow-green discharge with STRAWBERRY CERVIX (punctate hemorrhages) or an erythematous vaginal canal; treat patient AND partner with metronidazole. Gardnerella vaginalis (bacterial vaginosis): gram-negative rod, thin grey/watery discharge, positive whiff test, CLUE CELLS (squamous epithelial cells studded with bacteria). Candida: thick white cottage-cheese discharge in 2/3 of cases or an itchy erythematous vaginal canal without discharge; treat with topical nystatin or oral fluconazole." },
  { id: "re105", category: "STDs", q: "A Step 1 question treats candidiasis with an oral drug and asks the inhibited mechanism. Answer?", a: "P-450-mediated demethylation reaction. Fluconazole inhibits 14-alpha-demethylase in the conversion of lanosterol to ergosterol." },
  { id: "re106", category: "Syphilis", q: "Primary vs secondary vs tertiary syphilis?", a: "Treponema pallidum - a spirochete seen under dark-field microscopy. Primary: painless chancre (painless ulcer) on the genitalia. Secondary: 6 weeks to 6 months after the chancre appears and disappears - body rash including PALMS AND SOLES plus condylomata lata (painless genital plaques). Tertiary: years later - gummas, arthritis, and ascending aortitis (tree-barking of the vasa vasorum). Neurosyphilis can occur at ANY stage - not sequential." },
  { id: "re107", category: "Syphilis", q: "Neurosyphilis: the three presentations?", a: "1) Tabes dorsalis - obliteration of dorsal columns with loss of vibration/proprioception and a positive Romberg sign (falls with eyes closed). 2) Argyll-Robertson pupil - the 'prostitute pupil': accommodates but does not react. 3) 'Stroke without hypertension' - stroke-like findings in a younger patient." },
  { id: "re108", category: "Syphilis", q: "Syphilis diagnosis: which tests for which stage, how the VDRL works, and the lupus pearl?", a: "Primary: visualize spirochetes from a chancre scraping under dark-field microscopy. Secondary/tertiary/neuro: serology - VDRL or RPR first (sensitive but not specific), then FTA as confirmatory (specific but not sensitive). VDRL mixes patient serum with CARDIOLIPIN antigen causing clumping/flocculation; RPR adds charcoal particles. Patients with SLE and anti-phospholipid syndrome can have false-positive VDRL because of antibodies against cardiolipin (lupus anticoagulant). Young man with back rash and negative KOH prep -> FTA. All syphilis treated with penicillin - even with anaphylaxis history if pregnant or tertiary/neuro: desensitize and give penicillin; mere rash history, just give it." },
  { id: "re109", category: "STDs", q: "HSV 1/2 vs Haemophilus ducreyi genital ulcers?", a: "HSV: PAINFUL vesicular lesions recurring at varying intervals; primary most severe with fever, lymphadenopathy, herpetic neuralgia; can cause encephalitis (confusion + bloody CSF from temporal lobe hemorrhage) and herpetic whitlow; treat with acyclovir/valacyclovir. H. ducreyi causes chancroid: a PAINFUL single ulcer (gram-negative rod) that looks like a syphilitic chancre but is not - the syphilis ulcer is painless. Classic stem: single painful lesion after backpacking in Africa or South America. It is usually a DISTRACTOR for HSV: if a single painful lesion is a RECURRENCE, that is HSV (bacterial chancroid does not recur)." },
  { id: "re110", category: "PID", q: "PID: cause, buzzwords, and the tubo-ovarian abscess step?", a: "Caused by Chlamydia or Gonorrhea ascending the uterus and fallopian tubes, causing inflammation and scarring -> increased ectopic pregnancy risk (loss of tubal cilia -> premature implantation usually in the ampulla). Buzzwords: adnexal and especially cervical motion tenderness. A patient with PID on antibiotics plus PERSISTENT fever and adnexal pain gets an ultrasound to look for a tubo-ovarian abscess. Extension to the liver capsule = Fitz-Hugh-Curtis syndrome." },
  { id: "re111", category: "PID", q: "A hysterosalpingogram shows bilateral spillage of dye into the peritoneal cavity. Finding?", a: "NORMAL. The fallopian tubes are open on both ends - the fimbriae catch the ovum from the ruptured Graafian follicle - so bilateral dye spillage is expected; it is not tubal rupture. Prior PID can seal one or both tubes, showing FAILURE of spillage instead." },
  // ===== REPRO: TORCHes =====
  { id: "re112", category: "TORCHes", q: "Congenital toxoplasmosis: the HY triad?", a: "1) Hydrocephalus, 2) chorioretinitis, 3) intracranial calcifications in the neonate. They do not have to mention a litter box; can also be acquired from pork consumption." },
  { id: "re113", category: "TORCHes", q: "A pregnant woman has a flu-like illness and the fetus develops hydrops. Diagnosis and mechanism?", a: "Parvovirus B19. It can cause aplastic anemia in utero or the neonate (all three hematologic cell lines down, or pure RBC aplasia), with increased risk in sickle cell. Fetal hydrops = heart failure in utero, suggesting severe anemia from Parvo. Confirm with Parvo IgM titers in the neonate." },
  { id: "re114", category: "TORCHes", q: "Varicella (VZV) in pregnancy: congenital effects and the timing rule?", a: "VZV during pregnancy can cause microcephaly and limb hypoplasia. If mom contracts VZV for the FIRST time between 5 days before and 2 days after parturition, give varicella immunoglobulin to the neonate. If a neonate is exposed but mom previously had chickenpox or was vaccinated, no VZV IVIG - transplacental IgG gives the neonate passive immunity. Congenital VZV kids have increased risk of pediatric shingles; pregnant women who contract VZV can get pneumonia from it." },
  { id: "re115", category: "TORCHes", q: "Congenital rubella: the pass-level finding, and the MMR pregnancy rule?", a: "PDA in the neonate - exceedingly high yield; cataracts and deafness also possible. Mom does not need to have had a rash: adults can get only arthritis from rubella. MMR is live-attenuated and contraindicated in pregnancy; inadvertent vaccination near pregnancy is NOT an indication for abortion, but monitor." },
  { id: "re116", category: "TORCHes", q: "How do you distinguish congenital CMV from toxoplasmosis, rubella, and syphilis, and what is CMV's inclusion + drug?", a: "CMV is a diagnosis of exclusion: congenital deafness, hepatomegaly, blueberry muffin rash, and intracranial calcifications are all non-specific - toxo is the strict triad (hydrocephalus, chorioretinitis, calcifications), rubella always mentions PDA, and syphilis mentions teeth (mulberry molars/incisors), saber shins, or saddle nose. CMV causes OWL-EYE intranuclear inclusions. Tx = ganciclovir, a DNA polymerase inhibitor; resistance = alterations to viral thymidine kinase." },
  { id: "re117", category: "TORCHes", q: "Intrapartum management of maternal HSV and HIV?", a: "HSV: vaginal infection can transmit vertically causing neonatal encephalitis; if mom has prodromal symptoms (tingling, burning) even without visible lesions, do a C-section; women with predictable episodes get acyclovir 4-6 weeks before parturition. HIV: HAART immediately regardless of CD4 count, three-drug therapy; avoid efavirenz (NNRTI) in pregnancy; avoid TMP/SMX in the first trimester (OK in 2nd/3rd even with CD4 under 200); intrapartum zidovudine + C-section; neonate gets zidovudine within 6-12 hours of birth for 6 weeks. HIV is present in breastmilk - avoid breastfeeding even with undetectable viral load on HAART." },
  // ===== REPRO: Puberty =====
  { id: "re118", category: "Puberty", q: "Sequence of female puberty and what occurs immediately before it?", a: "Adrenarche (increased adrenal androgens -> pubic and axillary hair), thelarche (breast development), pubarche (pubic hair), menarche (onset of menses). USMLE answer for what occurs immediately before puberty in a female: breast bud development. At Tanner stage 3, 'menarche is imminent.'" },
  { id: "re119", category: "Puberty", q: "Turner vs androgen-insensitivity on Tanner staging?", a: "Turner syndrome: Tanner stage 1-2 breasts (shield chest) but Tanner 4-5 pubic/axillary hair - hair comes from ADRENAL, not ovarian, androgens, so it is preserved. AIS (46XY, female phenotype): breast development normal (Tanner 4-5) from aromatized estrogen, but pubic/axillary hair is Tanner stage 1 (scant/absent) since the androgen receptor is dead." },
  { id: "re120", category: "Puberty", q: "Bone age vs chronologic age: the growth interpretation?", a: "Bone age BELOW chronologic age = constitutional short stature - the short child will catch up (growth chart merely right-shifted; usually both parents average height). Example: 14-year-old shortest in class with bone age of 12, or pubic hair at Tanner 2 - he will catch up. Bone age EQUAL to chronologic age = genuine short stature, as in Turner syndrome (females usually under 5 feet)." },
  // ===== REPRO: Sex disorders =====
  { id: "re121", category: "Sex Disorders", q: "Turner syndrome: karyotype, fertility, hormones, and exam findings?", a: "45XO, female phenotype; only one X means NO Barr body on electron microscopy. Infertile due to streak ovaries - 'menopause before menarche' - but can still carry with IVF using a donor egg plus exogenous hormones. LH and FSH are both INCREASED from primary hypogonadism (decreased feedback from low ovarian hormones and inhibin). Findings: short stature (under 5 feet), Tanner 1-2 breasts (shield chest), cystic hygroma/webbed neck (lymphatic insufficiency), scattered nevi, and NORMAL pubic and axillary hair (adrenal androgens)." },
  // ===== REPRO: Sex disorders (cont.) =====
  { id: "re122", category: "Sex Disorders", q: "Turner mosaicism: what mechanism produces a 46XX/45XO somatic mosaic female, and the cardiac HV associations?", a: "Post-fertilization MITOTIC error. Turner also carries increased dysgerminoma risk from the streak ovaries (prophylactic oophorectomy recommended, especially with Y-chromosome material in mosaic forms). Cardio: coarctation of the aorta + bicuspid aortic valve (aortic stenosis) are the HY associations." },
  { id: "re123", category: "Sex Disorders", q: "Klinefelter syndrome: karyotype, body habitus, hormone directions, and cancer risk?", a: "47XXY, male phenotype. Tall, eunuchoid body; small testes; gynecomastia; reduced IQ; a Barr body (electron-dense mass) can be seen on electron microscopy. Dysgenesis of the seminiferous tubules leads to INCREASED LH and FSH (less feedback from low androgens and inhibin). Estrogen/androgen ratio is INCREASED from Leydig cell dysgenesis, and absolute estrogen is increased from more adipose tissue (more aromatase). Increased breast cancer risk; testicular cancer risk only very subtly increased, so NO prophylactic orchiectomy." },
  { id: "re124", category: "Sex Disorders", q: "Why do testes still develop in androgen-insensitivity syndrome, and where are they, plus the orchiectomy rule?", a: "The SRY gene on the Y chromosome induces differentiation of the primitive gonads into testes - this does not depend on androgens. The testes sit in the abdomen or inguinal canal and produce MIF, so there is NO uterus or fallopian tubes in AIS. Increased risk of testicular malignancy (dysgerminoma), so prophylactic orchiectomy is indicated AFTER puberty (to maximize estrogen-driven phenotypic female development), unless malignancy appears earlier. Next best step on the vignette: ultrasound first if listed, then karyotype." },
  { id: "re125", category: "Sex Disorders", q: "Mullerian agenesis vs AIS: identical vignettes except for ONE finding?", a: "Pubic/axillary hair. Both are 15-year-old girls who never had a period with a blind-pouch vagina. AIS: hair scant/absent (46XY, no Mullerian structures because the testes make MIF). Mullerian agenesis (Mayer-Rokitansky-Kuster-Hauser, 46XX): hair NORMAL/coarse - the ovaries are present (no SRY, so ovaries are the default) but the paramesonephric ducts never develop, so fallopian tubes, uterus, cervix, and upper vagina are missing. Next best step: ultrasound first, then karyotype." },
  { id: "re126", category: "Sex Disorders", q: "MIF deficiency: who has it and how is it found?", a: "46XY phenotypic male with testes (internal and external male structures present), but failure of Mullerian duct regression means a uterus, fallopian tubes, cervix, and upper vagina are ALSO present. Mullerian structures sit in the pelvis between bladder and rectum or in the inguinal canal, often discovered incidentally during orchidopexy for cryptorchidism - the question can describe undescended testes where surgery reveals a primitive uterus and fallopian tubes." },
  { id: "re127", category: "Sex Disorders", q: "SRY gene translocation: the two directions it can show up?", a: "Classic: 46XX + PHENOTYPIC MALE - the SRY gene from the Y translocates onto one X chromosome, making testes instead of ovaries; testosterone/DHT develop male external structures and MIF prevents Mullerian structures. Testes are usually small with hypo-/epispadias possible. Vignette: neonate appears male but karyotype is 46XX. Rare reverse: 46XY with the SRY gene LOST - no testes, instead streak ovaries plus Mullerian structures." },
  { id: "re128", category: "Sex Disorders", q: "CAH on Step 1: the simple 21- vs 11-hydroxylase decision tree?", a: "Ambiguous genitalia from 21-, 11-, or 17-hydroxylase deficiency. If 17-OH substrates (17-OH-pregnenolone, 17-OH-progesterone) and/or DHEA-S or androstenedione are HIGH, 17-hydroxylase deficiency is wrong - answer is 21 or 11. Then: LOW/normal BP or HIGH K+ = 21-deficiency; HIGH BP or normal/low K+ = 11-deficiency. 21-deficiency presents like Addison disease (high K+, low Na+, low bicarb, low pH, can have low glucose). Mechanism answer on a vignette of a 46XX girl with fused labia: ACTH hypersecretion (low cortisol -> ACTH rises to compensate, driving adrenal androgen excess). Do not memorize the full substrate pathways - pass/fail era." },
  { id: "re129", category: "Sex Disorders", q: "Swyer syndrome: the one-line contrast with AIS?", a: "46XY, phenotypically female from failure of the primitive gonads to become either testes or ovaries - they become STREAK gonads. Low androgen production gives the female phenotype and scant/absent pubic hair, and ABSENT MIF means Mullerian structures (uterus, tubes, cervix, upper vagina) DO develop. AIS is the mirror: Mullerian structures absent, androgens normal/increased with tissue insensitivity." },
  // ===== REPRO: Trisomies =====
  { id: "re130", category: "Trisomies", q: "Trisomy 21: three mechanisms and their percentages?", a: "Down syndrome = three chromosome 21s. 95%: meiotic nondisjunction in advanced maternal age (1/350 at 35, 1/100 at 40, 1/10 at 50). 4%: Robertsonian translocation - long arm of 21 attaches to another chromosome (usually 14) and is passed with two normal 21s. 1%: mosaic Down from post-fertilization mitotic (not meiotic) error." },
  { id: "re131", category: "Trisomies", q: "Down syndrome: mental retardation ranking, physical findings, and screens?", a: "Most common GENETIC cause of mental retardation (Fragile X is second; fetal alcohol syndrome is most common cause overall). Findings: flattened facies, slanted palpebral fissures, epicanthal folds, single palmar crease, gap between 1st and 2nd toes, Hirschsprung disease, duodenal atresia (double-bubble sign), endocardial cushion defects (AVSD/VSD/ASD), pulmonary artery malformations, ALL, congenital hypothyroidism, Eustachian tube atresia, Brushfield spots (iris lesions), hypoplastic nasal bone. First-trimester tri-screen (8-10 weeks): INCREASED nuchal translucency, INCREASED hCG, DECREASED PAPP-A. Second-trimester quad: DECREASED AFP, INCREASED hCG, DECREASED estriol, INCREASED inhibin A." },
  { id: "re132", category: "Trisomies", q: "Edward (18) vs Patau (13): findings that distinguish them?", a: "Trisomy 18 (Edward): low-set ears, prominent occiput, rocker-bottom feet, clenched hands with overlapping fingers, omphalocele or gastroschisis. Trisomy 13 (Patau, rare): holoprosencephaly (cyclopia - failure of the cerebral halves to separate) and polysyndactyly. Both usually fatal in utero or shortly after birth; quad arrows all down (inhibin normal in Patau) but USMLE does not care." },
  { id: "re133", category: "AFP", q: "A pregnant woman's AFP measures 2.6 times the upper limit of normal for her gestational age. Next best step?", a: "Ultrasound. The most common cause of an abnormal AFP measurement is DATING ERROR - the lab value is not wrong, the estimated gestational age is; ultrasound re-measures crown-rump length. Re-measuring AFP is the wrong answer." },
  { id: "re134", category: "AFP", q: "Too-high vs too-low AFP: what do the directions mean?", a: "Too high: neural tube defects (spina bifida, anencephaly), multiple gestation, omphalocele/gastroschisis - and dating error most commonly. Too low: 'down in Down syndrome' (also low in Edward and Patau, but USMLE ignores those)." },
  // ===== REPRO: Hemolytic disease of the newborn =====
  { id: "re135", category: "HDN", q: "Rh isoimmunization: who is at risk and what is the mechanism?", a: "~85% of people are Rh(+); Rh(-) women (~15%) are at risk of making IgG anti-Rh antibodies if the fetus is Rh(+) and the circulations mix. 'Rh isoimmunization' means she has developed IgG antibodies against Rh. Mechanism: Rh(-) mom is exposed to Rh(+) fetal blood in the first pregnancy and makes antibodies; in a SUBSEQUENT pregnancy, IgG crosses the placenta and targets fetal Rh(+) RBCs -> hemolysis in the fetus." },
  { id: "re136", category: "HDN", q: "RhoGAM: when is it given and when must it be withheld?", a: "Rh status is checked at the first antenatal screen (8-10 weeks). If mom is Rh(-), give RhoGAM at 28 weeks AND at parturition. Also give it for any intervention (amniocentesis) or complication (spontaneous abortion, abruptio placentae). Do NOT give RhoGAM during the pregnancy once an Rh(-) woman already has titers against Rh (2nd pregnancy onward) - it is too late." },
  { id: "re137", category: "HDN", q: "Kleihauer-Betke test: how does it work and why is it done?", a: "Done in an Rh(-) woman when hemorrhage or suspected fetomaternal mixing occurs. Mom's blood is drawn; the test exploits the resistance of HEMOGLOBIN F to acid, separating fetal RBCs from maternal cells on a smear. The fraction of fetal RBCs determines the dose of RhoGAM needed." },
  // ===== REPRO: Amniotic fluid =====
  { id: "re138", category: "Amniotic Fluid", q: "Polyhydramnios: the maternal and fetal causes?", a: "Excessive amniotic fluid. Maternal: GDM (increased fetal glucose pulls water through the fetal kidneys, increasing urinary volume) and multiple gestation (combined increased urinary output). Fetal: fetal hydrops - in Parvo B19, fetal anemia, or HDN, cardiac output rises to compensate, increasing renal perfusion and urine production; in fetal heart failure with low output, increased venous pressure causes edema and the kidneys ramp up urinary output to offload fluid." },
  { id: "re139", category: "Amniotic Fluid", q: "Oligohydramnios: causes and the Potter sequence?", a: "Insufficient amniotic fluid. Maternal cause: uteroplacental insufficiency (smoking, preeclampsia, SLE) compromising renal function and urinary output. Fetal causes: posterior urethral valves (most common genitourinary abnormality in neonatal males - membranes in the prostatic urethra block outflow, causing obstructive uropathy, vesicoureteral reflux, hydronephrosis; vignettes range from severe oligohydramnios to a male neonate who has not urinated), and renal agenesis (Potter sequence: no kidney development -> decreased urinary output -> decreased amniotic fluid -> impaired lung development -> pulmonary hypoplasia, plus flattened facies and rocker-bottom feet)." },
  // ===== REPRO: Hypertensive disorders =====
  { id: "re140", category: "Pregnancy HTN", q: "Chronic vs gestational hypertension, and the pregnancy-safe antihypertensives?", a: "Chronic: HTN before pregnancy or diagnosed BEFORE 20 weeks; usually persists postpartum. Gestational: new-onset HTN AFTER 20 weeks; typically resolves postpartum. Both managed with methyldopa (alpha-2 agonist), labetalol, or nifedipine; hydralazine for acute settings." },
  { id: "re141", category: "Preeclampsia", q: "Preeclampsia vs eclampsia: definitions, mechanism, and rules for magnesium?", a: "Preeclampsia = HTN + proteinuria AFTER 20 weeks' gestation (4/5 questions are just that). Eclampsia = preeclampsia + seizures. Mechanism is uteroplacental insufficiency - inadequate placental perfusion causes a compensatory cardiovascular drive to force perfusion, producing systemic HTN; can be idiopathic or secondary to smoking/SLE. Magnesium is given PROPHYLACTICALLY only in SEVERE preeclampsia (BP >160/110, proteinuria 3+, or multi-organ involvement - liver enzymes, visual disturbance/headache, pulmonary edema/cyanosis); for overt eclamptic seizures, magnesium is first-line. Definitive management for both is delivery." },
  { id: "re142", category: "Preeclampsia", q: "HELLP syndrome: the acronym and the smear?", a: "Hemolysis, Elevated Liver enzymes, Low Platelet count - a severe preeclampsia variant, and the question need not even mention proteinuria. HY: SCHISTOCYTES on blood smear from RBC shearing in damaged hepatic microvasculature; platelets fall from microvascular endothelial dysfunction with microthrombi. Schistocytosis + thrombocytopenia = microangiopathic hemolytic anemia (MAHA)." },
  { id: "re143", category: "Preeclampsia", q: "SLE and antiphospholipid syndrome in pregnancy: mechanism of miscarriage and prevention?", a: "Anti-phospholipid antibodies cause microthrombi in uteroplacental microvasculature -> decreased blood flow and fetal compromise -> recurrent miscarriage; if no miscarriage, IUGR and oligohydramnios from reduced oxygen delivery. Women with lupus antiphospholipid history get low-dose ASPIRIN + LMWH in subsequent pregnancies (warfarin is teratogenic). IUGR is best tracked by fetal ABDOMINAL circumference (reflects liver size and fat accumulation; brain is prioritized). SLE-related uteroplacental insufficiency is also a risk factor for preeclampsia." },
  // ===== REPRO: Thyroid in pregnancy =====
  { id: "re144", category: "Thyroid", q: "Which hormone raises thyroid-binding globulin in pregnancy, and what do the USMLE arrows look like?", a: "ESTROGEN (not progesterone) upregulates TBG production by the liver. For a euthyroid pregnancy, USMLE wants: TSH no change, FREE T4 no change, TOTAL T4 increased. Mechanism: TBG mops up free T4 so it transiently dips and TSH rises, stimulating more T4 production until free T4 normalizes and TSH is suppressed back - total T4 (free + TBG-bound) ends up higher. T3 is normal because free T4 is normal." },
  { id: "re145", category: "Thyroid", q: "Postpartum thyroiditis: the uptake pearl, plus levothyroxine, methimazole, and PTU rules in pregnancy?", a: "Postpartum (silent) thyroiditis can cause hypo- or hyperthyroidism after parturition; 131I uptake into the thyroid is LOW even when hyperthyroid (same for deQuervain and drug-induced thyroiditis - hormone leaks from inflamed cells rather than being overproduced, so TSH drops and the gland isn't stimulated). Levothyroxine in pregnancy: increase dose by 50%. Avoid methimazole in the first trimester (teratogenic). PTU is the answer for acute thyroid STORM in pregnancy despite 2nd/3rd-trimester hepatotoxicity concerns - the acute need eclipses that." },
  { id: "re146", category: "Vomiting", q: "What are the electrolyte/acid-base arrows for vomiting in pregnancy (both Step 1 and 2CK)?", a: "DECREASED K+, DECREASED Cl-, INCREASED HCO3-, INCREASED pH." },
  // ===== REPRO: Ectopic =====
  { id: "re147", category: "Ectopic Pregnancy", q: "Ectopic pregnancy: beta-hCG behavior and the single biggest risk factor?", a: "Implantation outside the uterus (including parametrium and cervix). Beta-hCG much LOWER than expected for gestational age - and remember beta-hCG should double every 2-3 days in early pregnancy, so questions mention a poor rate of rise. HY: risk is markedly increased with Hx of PID (tubal scarring and cilia disruption). Most frequent site is the ampulla (70-80%)." },
  // ===== REPRO: Pregnancy infections/surgery =====
  { id: "re148", category: "Pregnancy Infections", q: "Why is pyelonephritis risk increased in pregnancy, and why is asymptomatic bacteriuria treated?", a: "Two reasons: 1) progesterone slows ureteral peristalsis, increasing urinary stasis and backup to the kidney; 2) uterine compression of the ureters in the third trimester. Therefore asymptomatic bacteriuria is ALWAYS treated in pregnancy (unlike non-pregnant women). Nitrofurantoin is the classic drug for asymptomatic bacteriuria, standard UTIs, and cystitis in pregnancy." },
  { id: "re149", category: "Pregnancy Infections", q: "Cholelithiasis/cholecystitis/appendicitis in pregnancy: mechanism and the classic twist?", a: "Progesterone slows biliary peristalsis -> sludging; estrogen upregulates HMG-CoA reductase -> increased cholesterol synthesis -> stones. Colicky epigastric post-meal pain = cholelithiasis; add fever = cholecystitis; diagnose both with ultrasound (HIDA if ultrasound negative but suspicion high). Ursodeoxycholic acid (ursodiol) 'decreases cholesterol secretion into bile' and can shrink stones in pregnancy. HY twist: appendicitis can present as RIGHT UPPER QUADRANT pain in pregnancy because the 2nd-3rd trimester uterus pushes the appendix upward - a normal gallbladder ultrasound tells you it is not cholecystitis." },
  // ===== REPRO: Neonatal infections =====
  { id: "re150", category: "Neonatal Sepsis", q: "The three most common bacteria causing neonatal infections, and how stool-stain descriptions map to them?", a: "GBS, E. coli, and Listeria. Gram-positive cocci = GBS; gram-negative rods = E. coli; gram-positive rods = Listeria. Listeria is contracted by the pregnant woman via soft cheeses and deli meats." },
  // ===== REPRO: Peripartum bleeding =====
  { id: "re151", category: "Peripartum Bleeding", q: "Most common cause of postpartum bleeding, its exam finding, and its drug sequence?", a: "Uterine atony (70-80%) - vaginal bleeding with a large, BOGGY uterus. Uterine massage right after Stage 2 delivery reduces risk; refractory bleeding gets oxytocin to enhance tone and contractions, then ergonovine/methylergonovine (contraindicated in HTN, preeclampsia, MIGRAINE with aura, smokers, cardiovascular disease); uterine artery embolization or hysterectomy are last resort. Heme disorders like DIC, ITP, and vWD increase postpartum bleeding risk, and retained placental tissue is another cause." },
  { id: "re152", category: "Peripartum Bleeding", q: "Placenta previa vs abruptio placentae?", a: "Previa: placenta implants over the internal cervical os -> PAINLESS 3rd trimester bleeding; C-section from 37 weeks onward; prior uterine interventions (myomectomy, previous Cesareans) increase risk through abnormal implantation; before 36 weeks the implantation site can move off the os as the uterus grows. Abruption: placental detachment from the uterine wall before parturition -> PAINFUL 3rd trimester bleeding, often intense cramping; classic causes are COCAINE and deceleration injury (car accident)." },
  { id: "re153", category: "Peripartum Bleeding", q: "Accreta vs increta vs percreta?", a: "All cause postpartum bleeding. Accreta = placental attachment to the SURFACE of the myometrium. Increta = attachment into/inside the myometrium. Percreta = attachment THROUGH the myometrium, sometimes onto adjacent structures like the bladder (percreta = perforates)." },
  { id: "re154", category: "Peripartum Bleeding", q: "Vasa previa: the triad and the mechanisms behind it?", a: "Triad: 1) painless third-trimester bleeding, 2) rupture of membranes, 3) fetal bradycardia. Fetal vessels overlie the internal cervical os and are prone to shearing. Caused by velamentous cord insertion (vessels travel exposed in fetal membranes instead of being protected by Wharton jelly) or a succenturiate lobe (accessory placental lobe whose connecting vessels run across the os)." },
  { id: "re155", category: "Peripartum Bleeding", q: "Uterine inversion vs uterine rupture: how does each present after or during delivery?", a: "Inversion: uterus turns inside out following delivery of the placenta - postpartum bleeding and abdominal pain with the uterus NOT palpable abdominally; the stem may even say only gentle cord traction was applied. Rupture: uterine wall tears, associated with labor or previous uterine surgery (especially a classic VERTICAL Caesarean incision rather than low horizontal). Qu tell: oxytocin given + strong persistent contractions + now fetal parts palpable in the RUQ. Oxytocin causes tachysystole (>5 contractions/10 min averaged over 30 min) and hypertonus (contraction over 2 minutes; normal is every 2-5 minutes lasting 30-60 seconds), increasing rupture risk." },
  // ===== REPRO: Fetal monitoring =====
  { id: "re156", category: "Fetal Monitoring", q: "What do accelerations on a non-stress test mean?", a: "Fetal well-being. An acceleration is an INCREASE in fetal heart rate of ~20 bpm lasting ~20 seconds, occurring 2-3 times in a 20-minute period. The NST mostly shows up on 2CK/3 but is known to appear on Step 1." },
  { id: "re157", category: "Fetal Monitoring", q: "Early vs late vs variable decelerations: cause of each?", a: "Early: fetal HEAD compression - bradycardia at the same time as the uterine contraction (nadir and peak aligned), from increased vagal outflow with increased vascular resistance. Late: fetal HYPOXIA / uteroplacental insufficiency - bradycardia just AFTER the contraction; the bad type. Variable: umbilical CORD compression. Triad for late and variable decels: 1) stop all oxytocin, 2) maternal oxygen, 3) left-lateral decubitus positioning; then C-section if refractory. Fetal scalp pH <7.2 suggests acidosis/hypoxia." },
  { id: "re158", category: "Fetal Monitoring", q: "Amnioinfusion is the USMLE treatment for which deceleration pattern?", a: "Variable decelerations (umbilical cord compression) in the setting of prolonged or persistent decels." },
  // ===== REPRO: Fetal monitoring extras =====
  { id: "re159", category: "Fetal Monitoring", q: "A non-stress test shows a straight-line fetal heart rate WITHIN 110-160 bpm versus ABOVE that range. What are the answers?", a: "Straight line within the normal 110-160 bpm range = fetal sleep state. Straight line ABOVE the range (fetal tachycardia) = maternal fever." },
  // ===== REPRO: Sheehan =====
  { id: "re160", category: "Sheehan", q: "Sheehan syndrome: mechanism and the hormone arrows the NBME wants?", a: "The maternal pituitary grows during pregnancy due to increased hormone production; traumatic labor with major blood loss (low BP) causes anterior pituitary ischemic infarction. Textbook vignette: decreased ability to breastfeed from decreased milk production postpartum. All anterior pituitary hormones are low - NBME wants DECREASED prolactin, ACTH, AND TSH, plus INCREASED aldosterone (compensation for low basal BP from low cortisol; not overt hyperaldosteronism)." },
  // ===== REPRO: CV DDx of pregnancy =====
  { id: "re161", category: "Pregnancy CV DDx", q: "Acute shortness of breath and tachycardia 30 seconds to 2 minutes AFTER delivery of the placenta. Diagnosis and complication?", a: "Amniotic fluid embolism - amniotic fluid leaks into the maternal circulation and travels to the pulmonary arterioles. Can cause DIC with bleeding from IV lines/catheter sites. Treatment is supportive. Contrast with the answer at 2 days post-Cesarean when mom gets up from bed = pulmonary embolism." },
  { id: "re162", category: "Pregnancy CV DDx", q: "Peripartum cardiomyopathy: what it is and how you measure maternal/fetal risk for later pregnancies?", a: "Dilated cardiomyopathy almost always in the 3rd trimester or first few months postpartum; cause multifactorial, with some evidence for an autoantibody-mediated process. Presents as gradually worsening exertional dyspnea (left heart failure at minimum), with JVD and pitting edema if severe (right-sided findings). It WORSENS with each subsequent pregnancy; transthoracic echo for low ejection fraction is the diagnosis and the answer for determining risk in future pregnancies." },
  { id: "re163", category: "Pregnancy CV DDx", q: "Why do pregnant women get peripheral edema and IVC compression syndrome?", a: "Peripheral edema: increased plasma volume plus uterine compression of pelvic veins and IVC -> increased venous hydrostatic pressure. IVC compression (supine hypotensive) syndrome: 3rd-trimester woman gets lightheadedness, nausea, palpitations, shortness of breath, and BP drop while SUPINE due to reduced venous return from uterine IVC compression - fixed by left-lateral decubitus positioning." },
  { id: "re164", category: "Pregnancy CV DDx", q: "Atelectasis: the pass-level post-op fact and the obstructive form Step 1 likes?", a: "Most common cause of fever within 24 hours after surgery (even pass-level that a rare 2-days-out question exists). Mechanism: pain meds + sedation slow and shallow breathing, collapsing some alveoli; CXR shows bibasilar shadows/opacities. Step 1 also assesses obstructive (resorptive) atelectasis: lung distal to an obstruction (e.g., a tumor) collapses, increasing pneumonia risk distal to the obstruction." },
  { id: "re165", category: "Pregnancy CV DDx", q: "Budd-Chiari in pregnancy: what is it and why is the pregnant state hypercoagulable?", a: "Hepatic vein thrombosis from a hypercoagulable state like pregnancy - abdominal pain + hepatomegaly +/- ascites. Pregnancy hypercoagulability: the placenta produces plasminogen-activator inhibitor (PAI-2), decreasing plasmin activity and fibrinolysis; increased estrogen and progesterone increase fibrinogen, clotting factor, and vWF synthesis. Evolutionarily it decreases hemorrhage risk at parturition. (Similarly, progesterone relaxes vein walls and increases pelvic blood flow/pressure -> hemorrhoids in the 2nd-3rd trimester.)" },
  // ===== REPRO: Neonate =====
  { id: "re166", category: "NRDS", q: "Neonatal respiratory distress syndrome: cause, ratio, radiograph?", a: "Aka hyaline membrane disease - the answer for respiratory distress in a kid born <34 weeks. Insufficient surfactant production by type II pneumocytes from DECREASED lamellar bodies (the organelles producing surfactant). Lecithin/sphingomyelin ratio is LOW (<2.0; normal >2-2.4) - lecithin is aka dipalmitoyl phosphatidylcholine, and an NBME answer can be expressed as 'increased sphingomyelin' (lowering the ratio). Decreased surfactant means decreased alveolar compliance and increased elastic recoil - surfactant is hydrophobic and prevents alveolar collapse. CXR: buzzy RETICULOGRANULAR appearance. Prevention: mother delivering <34 weeks gets two boluses of corticosteroids within 24 hours of parturition to accelerate fetal lung maturity." },
  // ===== REPRO: Neonate (cont.) =====
  { id: "re167", category: "Neonate", q: "Sounds like NRDS but the kid is TERM and was delivered by C-section. Diagnosis and X-ray?", a: "Transient tachypnea of the newborn (TTN). A C-section or fast vaginal delivery leaves insufficient time for pulmonary lymphatics to clear amniotic fluid (and no birth-canal pressure to expulse it). CXR shows fluid within fissure lines. Management: tactile stimulation, then warming lights, then exogenous surfactant and oxygen if needed." },
  { id: "re168", category: "Neonate", q: "A 26-week preemie spends months on ICU oxygen and at 4 months is on home oxygen with right-axis deviation. Diagnosis and chain?", a: "Bronchopulmonary dysplasia - fibrotic lung disease from continued supplemental oxygen. RVH (ensuing cor pulmonale) from pulmonary hypertension explains the ECG right-axis deviation, and CXR can show increased pulmonary vascularity. Retinopathy of prematurity is the other oxygen-exposure complication." },
  { id: "re169", category: "Neonate", q: "Meconium aspiration syndrome: who, what it causes, and the persistent fetal circulation mechanism?", a: "Newborn aspirates meconium-stained amniotic fluid during parturition ('dark, meconium-stained fluid' in the stem); highest-yield risk factor is POST-TERM birth (after 40 weeks). Causes airway obstruction, infection, inflammation, dyspnea - and can trigger persistent fetal hypertension (persistent fetal circulation): the question gives a 42-week birth with meconium-stained fluid and a RIGHT-to-LEFT shunt across the foramen ovale on echo. The USMLE answer for the mechanism is 'failure of pulmonary vasodilation.' Meconium aspiration decreases opening of the lung vasculature, raising right heart pressure." },
  // ===== REPRO: Psych of pregnancy =====
  { id: "re170", category: "Repro Psych", q: "Postpartum blues vs depression vs psychosis: the timeline rule?", a: "Blues ('baby blues'): normal transient sadness, anxiety, mood swings, insomnia in the first week; resolves without intervention; thought due to hormonal shifts and adjustment. Over 10 days = think postpartum depression: persistent sadness/anxiety/exhaustion hindering care and bonding; THOUGHTS OF WORTHLESSNESS or guilt is the vignette answer; baby left crying or soiled uncovered diapers -> answer is immediate psychiatric referral; SSRIs (sertraline or paroxetine, low breast-milk concentrations). Postpartum psychosis: hallucinations, paranoia, harm to self or baby in the first few weeks - immediate psychiatric referral, antipsychotics (olanzapine or risperidone)." },
  { id: "re171", category: "Repro Psych", q: "Psych drug rules in pregnancy?", a: "Depression: sertraline first (lower risk profile); ECT for suicidal/homicidal ideation or refusal to eat/drink - considered safe for the fetus. Bipolar: AVOID lithium (Ebstein anomaly) and valproic acid (neural tube defects, cognitive impairment); use lamotrigine, olanzapine, or quetiapine." },
  { id: "re172", category: "Repro Psych", q: "PMS vs PMDD?", a: "PMS: mood swings, breast tenderness, irritability in the luteal phase (two weeks before menses), benign, from hormonal fluctuations. PMDD: severe incapacitating form dramatically interfering with socio-occupational functioning; SSRIs first-line." },
  // ===== REPRO: PCOS =====
  { id: "re173", category: "PCOS", q: "PCOS mechanism, from insulin resistance to hirsutism to cysts to endometrial cancer?", a: "High BMI -> insulin resistance -> abnormal GnRH pulsation -> INCREASED LH, DECREASED FSH (just the RATIO is high; FSH itself is low). Increased LH acts on theca-lutein cells to make androgens -> hirsutism. Decreased FSH causes poor follicular development, so the Graafian follicle fails to rupture and is retained as a follicular cyst. Failed ovulation = anovulation (irregular periods). No corpus luteum -> no progesterone to balance estrogen = unopposed estrogen -> endometrial hyperplasia -> endometrial carcinoma risk." },
  { id: "re174", category: "PCOS", q: "Anovulation vs PCOS: definitions and the differential with Cushing and hypothyroidism?", a: "Anovulation is the broader term - also caused by hypothyroidism and Cushing syndrome (glucocorticoids cause insulin resistance; hypothyroidism raises TRH, which stimulates prolactin, which disrupts GnRH pulsation). PCOS = anovulation + hirsutism in a high-BMI female, idiopathic (no known secondary etiology). 'High-BMI female + irregular periods = anovulation until proven otherwise.' NBME also asks: post-menopausal overweight woman + vaginal bleeding -> endometrial biopsy. PCOS patients have increased type II diabetes risk (baseline insulin resistance)." },
  // ===== REPRO: Progesterone withdrawal test =====
  { id: "re175", category: "Progesterone Test", q: "A positive vs failed progesterone withdrawal test: what does each prove in amenorrhea workup?", a: "Give progesterone and see if bleeding follows its withdrawal. BLEEDING (positive): estrogen levels are normal and the endometrium grows fine - anovulation is the cause (e.g., PCOS: no corpus luteum, so no progesterone present-then-withdrawn sequence, but estrogen is intact). NO BLEEDING: either estrogen is low (Turner, premature ovarian failure - the lining never developed) or the uterus is scarred (Asherman syndrome - estrogen normal, but adhesions prevent lining growth)." },
  // ===== REPRO: Dysmenorrhea =====
  { id: "re176", category: "Dysmenorrhea", q: "Primary dysmenorrhea: mechanism and the age/exam rule vs endometriosis?", a: "Prostaglandin PGF2-alpha hypersecretion from endometrial cells during menses, causing uterine contractions and pain (prostaglandins also enter the circulation causing headache and nausea). Answer for period pain UNDER 20 with a NORMAL physical exam - e.g., 17-year-old missing class for cramps. Tx NSAID (OCP is the wrong answer if listed alongside). In endometriosis the exam is ABNORMAL and the patient is over 20." },
  { id: "re177", category: "Dysmenorrhea", q: "Endometriosis: pathophys, classic exam findings, next best step?", a: "Growth of endometrial tissue outside the uterus - most common on the ovary, also the pouch of Douglas; mechanism is retrograde menstrual flow through the fallopian tubes seeding the ovary/peritoneum. Severe menstrual pain over age 20 with an ABNORMAL exam - any finding works: uterosacral ligament nodularity, fixed retroverted uterus, pelvic tenderness (pain with defecation and dyspareunia are pass-level but often omitted). Next best step: diagnostic laparoscopy; definitive treatment is laparoscopic removal of lesions (NSAIDs and OCPs are only short-term)." },
  { id: "re178", category: "Dysmenorrhea", q: "Adenomyosis: the classic question formulation?", a: "Growth of endometrial tissue WITHIN the myometrium. Diffusely enlarged uterus + vaginal bleeding in a woman 30s-50s (pain optional). Question: woman with a tubal ligation two years ago now has a uterus '8 weeks gestation size' + bleeding -> adenomyosis (she's not pregnant; they are describing the enlargement). Tx NSAIDs + OCPs." },
  { id: "re179", category: "Definitions", q: "Mittelschmerz, menorrhagia, metrorrhagia, dyspareunia, vaginismus?", a: "Mittelschmerz: benign ovulatory pain - sharp adnexal pain mid-cycle. Menorrhagia: heavy periods (>80 mL, can pass clots) and/or over 7 days. Metrorrhagia: mid-cycle bleeding (distinct from breakthrough bleeding of hormonal contraception users). Dyspareunia: persistent/recurrent pain during sex (seen in endometriosis). Vaginismus: dyspareunia from involuntary pelvic floor (especially pubococcygeus) contraction - spasmodic pain." },
  // ===== REPRO: Teratogens =====
  { id: "re180", category: "Teratogens", q: "Teratogens: ACE inhibitors, aminoglycosides, anti-epileptics, carbimazole/methimazole, DES?", a: "ACE inhibitors: renal issues. Aminoglycosides: hearing issues. Anti-epileptics: neural tube defects (disrupt folate metabolism) and fetal hydantoin syndrome (fingernail/digital hypoplasia, facial anomalies). Carbimazole/methimazole: aplasia cutis congenita, choanal atresia, esophageal atresia. DES: vaginal clear cell carcinoma 30-40 years later. Fetus most susceptible at 3-8 weeks." },
  { id: "re181", category: "Teratogens", q: "Teratogens: isotretinoin, lithium, methotrexate, NSAIDs, ribavirin, tetracyclines, thalidomide, warfarin?", a: "Isotretinoin: craniofacial and cardiac abnormalities, cleft lip/palate. Lithium: Ebstein anomaly ('atrialization' of the right ventricle. Methotrexate: neural tube defects. NSAIDs: premature closure of the ductus arteriosus, oligohydramnios, inhibited labor. Ribavirin: craniofacial anomalies, growth deficits. Tetracyclines: fetal teeth discoloration, inhibition of bone growth. Thalidomide: phocomelia (1950s-60s anti-nausea drug). Warfarin: bone and facial anomalies, CNS defects like Dandy-Walker malformation, fetal bleeding diathesis." },
  { id: "re182", category: "Substances", q: "Fetal alcohol syndrome: why is it the #1-mental-retardation answer and what does the face look like?", a: "Most common cause of mental retardation overall. Heart/lung defects from defective neural crest migration plus a distinct face: smooth, flat, and/or elongated philtrum; thin vermillion border (thin upper lip); widely spaced eyes (hypertelorism); midface hypoplasia; short nose. Also IUGR and cognitive deficits." },
  { id: "re183", category: "Substances", q: "Long vignette of drug use in pregnancy: what is most likely to occur, and the specific add-ons for cocaine and opioids?", a: "Amphetamines/cocaine: answer is 'preterm delivery and birth' - vague but most likely; cocaine also increases abruptio placentae risk. Heroin/opioids: neonatal withdrawal with piloerection, yawning, rhinorrhea. MDMA: IUGR, cognitive deficits. Smoking: IUGR and reduced IQ." },
  // ===== REPRO: Drugs =====
  { id: "re184", category: "Drugs", q: "Clomiphene: class and ovulation-induction mechanism?", a: "A selective-estrogen receptor MODULATOR used to stimulate ovulation in irregular cycles (particularly PCOS). Its partial-agonist effects at the hypothalamus are weaker than endogenous estrogen, so the hypothalamus reads it as ESTROGEN IS LOW -> decreased negative feedback -> INCREASED GnRH. Letrozole (aromatase inhibitor) stimulates ovulation by decreasing estrogen -> decreased negative feedback at the hypothalamus/anterior pituitary." },
  { id: "re185", category: "Drugs", q: "Danazol: receptor activity, classic non-repro use, and side effects?", a: "Androgen-receptor partial agonist. Classically used for hereditary angioedema (stimulates the liver to synthesize more C1-esterase inhibitor) and theoretically for endometriosis. Side effects: hirsutism and pseudotumor cerebri." },
  { id: "re186", category: "Drugs", q: "Methotrexate as Step 1 and 2CK ask it differently?", a: "2CK: given for small, stable ectopics (mother hemodynamically stable, no tubal rupture or peritoneal fluid, ectopic <3.5 cm, beta-hCG under 5000). For Step 1: just know it is a dihydrofolate reductase inhibitor that interferes with folate metabolism." },
  { id: "re187", category: "Drugs", q: "SERMs: tissue logic for tamoxifen vs raloxifene and tamoxifen's own cancer risk?", a: "SERMs act differently by tissue. Tamoxifen and raloxifene both are ANTAGONISTIC at the breast (used for ER-positive breast cancer) and AGONISTIC at bone. Tamoxifen increases endometrial cancer risk because it is AGONISTIC at the endometrium." },
  { id: "re188", category: "Drugs", q: "Minoxidil and tocolytics?", a: "Minoxidil: arteriolar dilator promoting hair growth in ANDROGENETIC alopecia (which is polygenic, risk increased with anabolic steroids). Tocolytics suppress labor by decreasing uterine contractions to allow time for corticosteroid boluses for fetal lung maturity: terbutaline (mixed beta-1/2 agonist), ritodrine (beta-2 agonist), nifedipine are HY; indomethacin and magnesium are also possible." },
  { id: "re189", category: "Drugs", q: "Finasteride, tamsulosin, and BPH pharm - exact mechanisms?", a: "Finasteride: 5-alpha reductase inhibitor - decreases conversion of testosterone to DHT, and since DHT causes prostatic growth, growth decreases. Tamsulosin/terazosin: alpha-1 blockers that decrease constriction of the INTERNAL URETHRAL sphincter of the bladder, promoting urinary outflow." },
  { id: "re190", category: "Drugs", q: "Magnesium sulfate in Obgyn: the four settings?", a: "1) Severe preeclampsia - seizure prophylaxis (prevent eclampsia). 2) Eclampsia - treats the seizures. 3) Women delivering <32 weeks - neuroprotective for the neonate. 4) In theory a tocolytic. Also note the pregnancy HTN drugs: methyldopa (alpha-2 agonist), labetalol, nifedipine classically; hydralazine for HTN emergencies." },
  { id: "re191", category: "Drugs", q: "Bromocriptine for prolactinoma: class?", a: "Dopamine D2 receptor AGONIST (ergot alkaloid). Dopamine is the endogenous prolactin inhibitor, so bromocriptine shrinks prolactinomas." },
  // ===== REPRO: Rapid-review embryo extras =====
  { id: "re192", category: "Embryology", q: "Week-by-week embryo specifics the bullet review adds: 2 weeks, 3 weeks, 3-4 weeks, 4 weeks?", a: "At 2 weeks the embryo has 2 layers (EPIBLAST + HYPOBLAST). At 3 weeks, neural tube development begins (completed by week 4). Between 3-8 weeks most organogenesis occurs; the fetal heartbeat does not start until week 4. The 3-4-week window is when the fetus is most susceptible to NEURAL TUBE defects (folate deficiency, valproic acid and anti-epileptics causing folate malabsorption); for teratogens generally, pick 3-4 weeks if listed, else 3-8 weeks." },
  { id: "re193", category: "Embryology", q: "The CAP mnemonic plus what actually matters for ectoderm, mesoderm, and endoderm?", a: "CAP = Clefts (grooves) become ectoderm; Arches become mesoderm; Pouches become endoderm. Ectoderm HY: skin + anal canal BELOW the pectinate line. Mesoderm HY: muscle + connective tissue; spleen + kidneys. Endoderm HY: esophagus and GI lining UNTIL the pectinate line; parathyroids + thymus. If totally lost on an embryo derivative question, neural crest is right about 3/4 of the time; pheochromocytoma, melanoma, and neurofibromatosis I/II are also neural crest." },
  { id: "re194", category: "Embryology", q: "Pharyngeal arch nerve assignments #1, #2, #3, #4, #6?", a: "Arch 1 -> CN V (muscles of mastication). Arch 2 -> CN VII (muscles of facial expression, stapedius, platysma). Arch 3 -> CN IX (stylopharyngeus). Arch 4 -> superior laryngeal nerve branch of CN X (cricothyroid). Arch 6 -> recurrent laryngeal nerve branch of CN X (laryngeal muscles, but not cricothyroid). The 5th arch has no major contributions." },
  // ===== REPRO: Rapid-review nuggets =====
  { id: "re195", category: "Embryology", q: "Foregut/midgut/hindgut: arteries, levels, and spans - plus the spleen trick?", a: "Foregut: celiac trunk (T12), esophagus to 1st part of duodenum. Midgut: SMA (L1), 2nd part of duodenum to distal 2/3 of transverse colon. Hindgut: IMA (L3), last third of transverse colon to the anal canal at the pectinate line. L2 (between SMA and IMA): renal arteries and gonadal (testicular/ovarian) arteries. Weird factoid: 'organ supplied by an artery of the foregut but not derived from the foregut' = SPLEEN - supplied by the celiac trunk, but mesoderm-derived (listed as midgut in his notes) - know it as the classic exception." },
  { id: "re196", category: "Placenta", q: "Placenta components and the oxygen/antibody transfer rules?", a: "Two components: fetal trophoblast (syncytiotrophoblast = deep, cytotrophoblast = superficial) + maternal decidua. The syncytiotrophoblast secretes hCG to maintain the corpus luteum. Fetal and maternal circulations do NOT mix - gas/nutrients exchange across the placenta, and fetal hemoglobin (alpha-2 gamma-2) has higher oxygen affinity than maternal (alpha-2 beta-2), pulling O2 across. IgG from the mother crosses the placenta; IgA is passed through BREAST milk." },
  { id: "re197", category: "Amniotic Fluid", q: "Rapid-review adds two fetal causes of polyhydramnios - what are they and why?", a: "Fetal anencephaly and tracheoesophageal fistula - because the fetus can't swallow amniotic fluid properly (plus maternal diabetes with fetal polyuria: insulin itself does not cross the placenta, only glucose does). Oligohydramnios (maternal smoking/cocaine, maternal SLE/antiphospholipid - uteroplacental insufficiency - plus fetal Potter sequence and posterior urethral valves from decreased urination)." },
  { id: "re198", category: "Twinning", q: "Alternate day-based twin-splitting map: 0-4, 5-8, 9-12, 12+?", a: "Days 0-4: dichorionic-diamniotic (two placentas, two yolk sacs, thick dividing membrane). Days 5-8: monochorionic-diamniotic (one shared placenta, no thick dividing membrane, but two amniotic sacs and thus two yolk sacs). Days 9-12: monochorionic-monoamniotic (single placenta and yolk sac - greatest twin-twin transfusion risk). After day 12: conjoined twins. Rules: number of placentas = number of chorions; number of amnions = number of yolk sacs; the yolk sac comes from the hypoblast and the amnion from the epiblast." },
  { id: "re199", category: "Embryology", q: "Umbilical cord contents beyond the vessels: the allantois and urachus?", a: "The cord holds one umbilical vein (oxygenated), two umbilical arteries (deoxygenated - derived from the fetal INTERNAL ILIAC arteries, not veins), and the allantois (tube carrying fetal urine from the bladder back to the placenta), all wrapped in Wharton jelly. The urachus is the thick fibrous part of the allantois inside the fetal body (bladder to umbilicus); post-birth it closes into the MEDIAN umbilical ligament. If patent, neonate's urine comes out through the umbilicus - patent urachus / urachal cyst / diverticulum." },
  { id: "re200", category: "Embryology", q: "The vitelline (omphalomesenteric) duct: what does it connect and what happens if it stays open?", a: "Connects the fetal midgut lumen to the yolk sac. Failure to fully involute -> MECKEL diverticulum." },
  { id: "re201", category: "Embryology", q: "Cleft lip and palate: exact NBME embryology phrases?", a: "Cleft lip: 'failure of fusion of maxillary and medial nasal processes.' Cleft palate: 'failure of fusion of lateral palatine shelves.' Cause answer: polygenic/multifactorial; recurrence to a second child 3-4% (similar for ASD/VSD and pyloric stenosis)." },
  { id: "re202", category: "Embryology", q: "Wolffian duct structures: the SEED mnemonic?", a: "SEED: Seminiferous tubules, Epididymis, Ejaculatory duct, Ductus deferens. SRY -> testes (90% seminiferous tubules) -> Leydig testosterone (needed for Wolffian/internal male structures) -> DHT via 5-alpha reductase (needed for the prostate and external male structures - penis)." },
  { id: "re203", category: "Embryology", q: "What are all four Sertoli cell products?", a: "1) Mullerian inhibitory factor (MIF) - shuts off female structures. 2) Androgen-binding protein - keeps local testosterone high in the seminiferous tubules for sperm production. 3) Inhibin B - negative feedback at the hypothalamus for GnRH. 4) Aromatase - converts androgens to estrogens." },
  { id: "re204", category: "Hormones", q: "Androgens vs inhibin B: which shuts off LH more versus FSH more, and what is the menopause marker?", a: "Androgens have the stronger effect shutting off LH; inhibin B has the stronger effect shutting off FSH. In Turner, premature ovarian failure, and menopause, low estrogen -> high LH (no negative feedback) and low inhibin B -> high FSH. HIGH FSH is the exceedingly HY marker of menopause." },
  { id: "re205", category: "Gyn Ligaments", q: "What does uterine didelphys vs bicornuate uterus mean on a hysterosalpingogram image?", a: "A uterus with a septum running down the middle = BICORNUATE uterus (increased premature delivery and miscarriage risk; mechanism = failure of paramesonephric ducts to fuse). A complete double uterus = uterine DILIEPHYS." },
  // ===== REPRO: Nuggets round 2 =====
  { id: "re206", category: "Embryology", q: "Male-female homologues: recite the four rows.", a: "Genital tubercle: glans penis = glans clitoris; corpus cavernosum/spongiosum = vestibular bulbs. Urogenital sinus: prostate = glands of Skene (urethral/paraurethral); bulbourethral (Cowper) glands = greater vestibular (Bartholin) glands. Urogenital folds: ventral shaft (underside) of penis = labia minora. Labioscrotal swelling: scrotum = labia majora." },
  { id: "re207", category: "Male Pathology", q: "Posterior urethral valves: presentations and the diagnostic sequence (with the name traps)?", a: "Most common GU abnormality in fetal/neonatal males: the valves point the wrong direction and prevent urine excretion. Severity runs from oligohydramnios to a newborn male who has not urinated (suprapubic mass = full bladder) to an infant male with recurrent UTIs/pyelonephritis. Diagnosis: ULTRASOUND first, then VOIDING cystourethrogram - do not confuse with a retrograde urethrogram (used to Dx urethral injury) or retrograde cystourethrogram (bladder injury). Treatment: surgical." },
  { id: "re208", category: "Male Pathology", q: "The cremasteric reflex: what nerve mediates it?", a: "The genitofemoral nerve. The reflex is retraction of scrotal skin with palpation of the medial thigh; it is INTACT in epididymitis and ABSENT in testicular torsion; positive Prehn sign (relief with elevation) argues epididymitis as well." },
  { id: "re209", category: "Anatomy", q: "Lymphatic drainage: testes vs scrotum vs ovaries - and the gonadal artery rule?", a: "Testes and ovaries drain to the PARA-AORTIC lymph nodes. The SCROTUM drains to the superficial inguinal nodes, not para-aortic. Testicular and ovarian ('gonadal') arteries come directly off the abdominal aorta at L2." },
  { id: "re210", category: "Gyn Ligaments", q: "Ligation risk: which two surgeries put the ureter at risk through which ligaments?", a: "Oophorectomy ligating the OVARIAN vessels - runs through the SUSPENSORY ligament of the ovary. Hysterectomy ligating the UTERINE vessels - run through the CARDINAL ligament. Both risk ureter injury ('water under the bridge'). Round ligament connects the uterine horns (superolateral uterus) to the labia majora; parametrium = fat and connective tissue surrounding the uterus (a developing embryo there = ectopic pregnancy)." },
  { id: "re211", category: "Histology", q: "Reproductive histology: epithelium of vagina/ectocervix vs uterus/tubes vs ovaries, and the transformation zone?", a: "Vagina and ectocervix: stratified squamous. Uterus and fallopian tubes: simple columnar (tubes are ciliated). Ovaries: simple cuboidal. The transformation zone of the cervix is the squamocolumnar junction between the stratified squamous ectocervix and the simple columnar endocervix - where cervical SCC arises." },
  { id: "re212", category: "Histology", q: "Endometrial histology through the cycle, plus the Sertoli/Leydig histology distinction?", a: "Proliferative/follicular phase: straight/tubular glands. Secretory/luteal: coiled glands - EARLY luteal has coiled glands with no secretions in lumens; LATE luteal has coiled glands WITH secretions in the lumens. In the testis, Sertoli cells are more linear and form the blood-testes barrier; Leydig (interstitial) cells are the randomly distributed non-linear cells." },
  { id: "re213", category: "Hydatidiform Moles", q: "The bullet-review version of complete vs partial mole fertilization - restate it precisely?", a: "Complete mole: an EMPTY egg fertilized by two sperm, or by a single sperm that duplicates - ALL genetic material is PATERNAL, karyotype 46 (XX), no fetal parts, snowstorm/bunch-of-grapes ultrasound, higher risk of choriocarcinoma. Partial mole: a NORMAL ovum fertilized by two sperm - karyotype 69, fetal parts present, lower (but real) choriocarcinoma risk." },
  { id: "re214", category: "Ovarian Cancer", q: "Which ovarian tumors have psammoma bodies, and which tumor is the gastric mets one?", a: "Psammoma bodies (calcium concretions): serous cystadenoma/cystadenocarcinoma of the ovary. Krukenberg tumor: gastric cancer metastatic to both ovaries with mucin-containing signet-ring cells." },
  // ===== REPRO: Nuggets round 3 =====
  { id: "re215", category: "Ovarian Cancer", q: "Dysgerminoma: the two clinical hints beyond LDH?", a: "High LDH plus a PULLING SENSATION IN THE GROIN. Also: struma ovarii is the ovarian germ-cell tumor making thyroid hormone; Brenner has transitional (bladder) epithelium; gyn cancers in general have increased risk in BRCA1/2 and HNPCC." },
  { id: "re216", category: "Testicular Cancer", q: "Seminoma: age range, exam description, and risk associations?", a: "Most common testicular cancer, classically ages 15-35. Hard nodule or mass that does NOT transilluminate; can be discovered incidentally after trauma on NBME. Increased risk with cryptorchidism and Klinefelter. Histology shows large clear cells; highly radiosensitive (responds even if metastasized); can produce placental ALP as a tumor marker." },
  { id: "re217", category: "Breast", q: "Intraductal papilloma vs inflammatory carcinoma vs comedocarcinoma vs invasive lobular?", a: "Intraductal papilloma: UNILATERAL BLOODY NIPPLE discharge - do not confuse with DCIS. Inflammatory carcinoma: red/inflamed painful breast, classically PEAU D'ORANGE (mottled skin from tethering of edematous skin by the Cooper ligaments). Comedocarcinoma: cheese-like breast cancer. Invasive lobular: LCIS that crossed the basement membrane; lobular types can be bilateral with linear 'Indian rows' of cells." },
  { id: "re218", category: "Breast", q: "DCIS management question on the NBME: next step and the wrong answer?", a: "Needle-guided OPEN biopsy; FNA is the wrong answer for that question. And Paget disease of the breast (eczematoid nipple in a woman over 50 with an underlying nipple mass) = underlying DCIS." },
  { id: "re219", category: "Hormones", q: "Where exactly is oxytocin produced, and which hypothalamic nucleus is it?", a: "Produced by the SUPRAOPTIC nucleus of the hypothalamus and stored in the posterior pituitary; causes milk letdown (release) and stimulates uterine contractions. Prolactin (anterior pituitary) stimulates milk PRODUCTION." },
  { id: "re220", category: "Puberty", q: "Precocious puberty: age cutoffs, height pattern, and the lab triage?", a: "Secondary sex characteristics at age 8 or younger in females, 9 or younger in males. Childhood height increased but adult height DECREASED. Is it central (hypothalamus/pituitary axis)? Check LH: high LH means central; LOW LH means primary testicular testosterone production. If DHEA-S is abnormally high, the ADRENAL gland (zona reticularis secretes DHEA-S and androstenedione) is the cause." },
  // ===== REPRO: Pharm nuggets + vignettes =====
  { id: "re221", category: "Drugs", q: "Mifepristone, misoprostol, ulipristal, dinoprostone: classes and uses?", a: "Mifepristone: progesterone receptor ANTAGONIST, abortifacient (used up to 10 weeks). Misoprostol: prostaglandin E1 analogue, used 1-2 days after mifepristone. Ulipristal: selective progesterone receptor modulator, emergency contraception (effective within 5 days; levonorgestrel is within 3). Dinoprostone: prostaglandin E2 analogue used to soften/ripen the cervix." },
  { id: "re222", category: "Drugs", q: "Trastuzumab: target and its must-know toxicity?", a: "Targets HER2/neu(+) breast cancer; the must-know toxicity is CARDIOTOXICITY." },
  { id: "re223", category: "Drugs", q: "Why is flutamide always given before leuprolide in prostate cancer?", a: "Leuprolide (continuous GnRH agonist) causes a TRANSIENT increase in LH and FSH before receptor desensitization - the LH bump can transiently raise testosterone and feed the tumor. Flutamide (androgen-receptor antagonist) given first blocks the receptors during that window." },
  { id: "re224", category: "Breast", q: "31F two days postpartum, bottle-feeding, with engorged tender breasts + fever of 101F + dysuria with normal urinalysis. Diagnosis?", a: "Breast engorgement. Sounds like an obvious infection, but the learning point is engorgement can present with FEVER, and occasional dysuria with a normal U/A is not atypical. Mastitis vs abscess hinge: warm/red/non-fluctuant = mastitis (S. aureus, dicloxacillin or cephalexin, keep breastfeeding), fluctuant = abscess (drain first, before antibiotics)." },
  { id: "re225", category: "Definitions", q: "A 24F with amenorrhea since a D&C 13 months ago for postpartum hemorrhage has no bleeding on a progestin withdrawal test. Diagnosis, and what is the 10-year risk if untreated?", a: "Asherman syndrome (uterine synechiae) - scarring after instrumentation. The failed withdrawal test tells you estrogen is low (or here the uterus is scarred; either way the classic taught risk): chronic LOW ESTROGEN -> OSTEOPOROSIS if untreated." },
  { id: "re226", category: "Osteoporosis", q: "Best way a 45F can decrease osteoporosis risk, versus best intervention in a 72F who already has it?", a: "45-year-old: weight-bearing exercise, NOT calcium plus vitamin D. 72-year-old with osteoporosis: going on long WALKS most greatly decreases fracture risk - swimming/pool exercise is the wrong answer despite the falls-risk logic. And the strongest predisposing risk factor in a Caucasian woman with a vertebral compression fracture: RACE (white race), over alcohol, beta-blocker use, nulliparity, or HTN." },
  { id: "re227", category: "Vignettes", q: "23F at 10 weeks' gestation, nausea and vomiting for 4 weeks, lost 1.8 kg. Most likely adverse effect on the fetus?", a: "No significant adverse effect. (Hx and mechanism: hyperemesis gravidarum presents at 8-10 weeks from the PEAK beta-hCG at that time; Dx = urinary ketones; hypokalemic, hypochloremic metabolic alkalosis; Tx = IV anti-emetics - metoclopramide/ondansetron - since she can't keep oral intake down.)" },
  { id: "re228", category: "Vignettes", q: "Amenorrhea in anorexia vs premature ovarian failure/Turner/menopause: the FSH + estrogen answer pairs?", a: "Anorexia: DECREASED FSH, DECREASED estrogen (hypogonadotropic, central - low GnRH pulsation). Premature ovarian failure, Turner syndrome, and menopause: INCREASED FSH, DECREASED estrogen (primary ovarian failure). Metoclopramide is the other big drug cause of hyperprolactinemia besides antipsychotics (D2 antagonist)." },
  { id: "re229", category: "Breast", q: "A breast complex cyst is aspirated (straw-colored fluid) but the mass is still present. Next best step?", a: "Biopsy of the mass. And rusty nipple discharge in a 45F = intraductal papilloma until proven otherwise - unless the biopsy shows stellate morphology, which is invasive ductal carcinoma." },
  { id: "re230", category: "Puberty", q: "11F with Tanner stage 3 breast and pubic hair: what do these findings predict?", a: "Menarche is imminent. Normal sequence: adrenarche -> thelarche -> pubarche -> menarche. A 13F still at Tanner stage 2 who has never menstruated gets follow-up in 6 months - menarche is not yet imminent at stage 2." },
  // ===== REPRO: Vignette nuggets round 2 =====
  { id: "re231", category: "Vignettes", q: "42F + recurrent miscarriage + SLE, and what treatment rule follows?", a: "Antiphospholipid syndrome (lupus anticoagulant) - the mechanism answer is UTEROPLACENTAL insufficiency. Treat subsequent pregnancies with aspirin or heparin (LMWH); warfarin is contraindicated (fetal bone abnormalities and bleeding). Bonus: an SLE patient commencing her third course of corticosteroids in 18 months should get ALENDRONATE now - give bisphosphonates to patients on steroids indefinitely or frequently." },
  { id: "re232", category: "Vignettes", q: "IUGR: top lifestyle factor, the confirming test, and the best fetal parameter?", a: "SMOKING (not alcohol) most contributes -> decreased placental blood flow -> confirm with Doppler ultrasonography of the umbilical artery. Best fetal parameter for IUGR: ABDOMINAL circumference (not femur length or biparietal diameter). A 23F at 33 weeks with a Factor V Leiden mutation and intrauterine fetal demise: the thrombosis most likely occurred in the UTEROPLACENTAL artery." },
  { id: "re233", category: "Thyroid", q: "Thyroid workup rules in pregnancy and the thionamide trimester map?", a: "Order FREE T4 when asked to evaluate thyroid function in pregnancy (TSH screens non-pregnant people; free T4 is the most definitive marker anyway). Levothyroxine may need to increase up to 50%. Thionamides: methimazole is teratogenic FIRST trimester (aplasia cutis congenita) - give PTU in first trimester - then 2nd trimester onward SWITCH back to methimazole (PTU is significantly hepatotoxic and methimazole is only teratogenic early). Thyroid storm in pregnancy: PTU." },
  { id: "re234", category: "Thyroid", q: "Postpartum thyroiditis: phases, timing, cause, and treatment?", a: "A silent thyroiditis affecting 5-10% of women postpartum, thought to be a postpartum immunologic rebound (immune system is normally suppressed in pregnancy). Hyperthyroid phase usually 1-4 months postpartum; hypothyroid phase 4-8 months; a third of women get both phases, a third only hyper, a third only hypo. Vignette: 6 months postpartum, dry skin, enlarged non-tender thyroid, high TSH, low T4 -> postpartum thyroiditis. Diagnose with history + serum TSH; short-course propranolol if hyper, short-course levothyroxine if hypo; increased risk of progression to Hashimoto. Cretinism is preventable with routine NEWBORN SCREENING." },
  { id: "re235", category: "Ovarian", q: "8 weeks' gestation with bilateral cysts on pelvic ultrasound. Diagnosis, natural history, and associations?", a: "Theca-lutein cysts - benign, almost always regress naturally; increased occurrence in high beta-hCG states: multiple gestation, moles, choriocarcinoma." },
  { id: "re236", category: "Vignettes", q: "40F with vasomotor symptoms: which hormone confirms premature ovarian failure, and the autoimmune curveball?", a: "HIGH FSH. And a 28F with Hashimoto thyroiditis, 6 months of hot flashes, and high FSH -> 'autoimmune ovarian failure' as a cause of premature ovarian failure (autoimmune diseases travel together)." },
  { id: "re237", category: "PCOS", q: "PCOS treatment and the T2DM trap vignette?", a: "If high BMI, WEIGHT LOSS is first on the USMLE. Meds: OCPs if she does not want pregnancy; clomiphene if she wants pregnancy (estrogen-receptor partial agonist -> increased GnRH outflow -> ovulation). 32F unable to conceive 3 years + BMI 30 + acanthosis nigricans -> answer = T2DM (PCOS/anovulation not listed); hypercortisolism is the wrong answer because no purple striae, muscle wasting, or central obesity are mentioned." },
  { id: "re238", category: "Neonate", q: "Caput succedaneum vs cephalohematoma, with the color trap?", a: "Caput: poorly-defined soft tissue edema of the scalp from pressure against the cervix (transient decreased blood flow, reactive edema) - CROSSES suture lines; resolves in hours to days; benign. Cephalohematoma: well-defined, localized, fluctuant swelling from subperiosteal hemorrhage - does NOT cross suture lines; can be associated with skull fracture, clotting disorders, jaundice (bilirubin from reabsorption); resolves in weeks to months. Both can be purplish - color doesn't separate them." },
  // ===== REPRO: Vignette nuggets round 3 =====
  { id: "re239", category: "Vignettes", q: "18F using tampons + diffuse rash + BP 90/60. Diagnosis and agent?", a: "Toxic shock syndrome - S. aureus TSST superantigen. Tampon use (or vulvovaginal/perineal skin infection; cotton nasal packing on non-Obgyn questions). The superantigen bridges MHC-II on macrophages with the TCR on CD4+ T cells, driving cytokine release and shock; the Obgyn question asks most likely cause of death = ARDS." },
  { id: "re240", category: "Vignettes", q: "36F at 26 weeks with severe flank pain and near-syncope on urination. Mechanism?", a: "Urolithiasis - progesterone slows ureteral peristalsis in pregnancy, increasing stone opportunity. (Pregnancy stone analog: progesterone also slows biliary peristalsis while estrogen increases HMG-CoA reductase activity -> cholesterol gallstones.)" },
  { id: "re241", category: "Vignettes", q: "A 25F with normal periods 20 days post-LMP has a 5-cm mobile, slightly tender right adnexal mass. Diagnosis and wrong answer?", a: "Hemorrhagic corpus luteum cyst. Wrong answer: endometrioma (chocolate cyst of endometriosis). Also: 26F with dull pelvic pain and a cystic mass showing CALCIFICATION on ultrasound = dermoid cyst (mature cystic teratoma) - the hair/skin/teeth details are too easy for the modern forms." },
  { id: "re242", category: "Seizure", q: "31F with epilepsy at 10 weeks' gestation has a seizure with a sub-therapeutic phenytoin level. Next step, and the valproic acid rule?", a: "INCREASE the phenytoin dose - yes, during pregnancy - because a seizure causes fetal hypoxia, the worst-case scenario. But a woman ON valproic acid wanting to conceive: STOP it (high neural-tube-defect risk) and swap to other anti-epileptics." },
  { id: "re243", category: "Incontinence", q: "52F with hot flashes + urge incontinence: the mechanism answer? Plus the one-liner mechanisms for stress and overflow.", a: "Estrogen deficiency. Stress incontinence has also been answered as 'decreased external urethral tone' with downward movement of the vesicourethral junction. Overflow in diabetes = neurogenic bladder (bethanechol); overflow in BPH = outlet obstruction -> eventual neurogenic bladder (treat the BPH first). Mirabegron (beta-3 agonist) exists for urge, but oxybutynin is the NBME answer." },
  { id: "re244", category: "Vignettes", q: "Atrophic vaginitis in TWO life stages: the shared mechanism?", a: "HYPOESTROGENIC state. 57F with blood-stained underwear, painful sex, and atrophic friable mucosa -> atrophic vaginitis; Tx lubricants first, then topical estrogen. 25F currently breastfeeding with dyspareunia + erythematous vagina and no discharge: same picture because HIGH PROLACTIN during breastfeeding creates a hypoestrogenic state - next best step is just a lubricant recommendation." },
  { id: "re245", category: "OCPs", q: "Combined OCPs and cancer risk: the exact directional profile?", a: "DECREASED ovarian (~50% reduction) and DECREASED endometrial cancer (synchronization of cycles); roughly NEUTRAL for breast (some suggest slight increase without significance); INCREASED cervical cancer risk - not from the pill directly but from decreased barrier contraception use with more HPV exposure. A 16F whose aunt died of ovarian cancer asking how to screen: no screening - OFFER INFORMATION ABOUT OCPs." },
  { id: "re246", category: "Vignettes", q: "43F on IVF with severe abdominal pain and ascites after beta-hCG administration. Diagnosis and mechanism?", a: "Ovarian hyperstimulation syndrome - almost always from iatrogenic beta-hCG (or clomiphene) administration, causing vascular HYPERPERMEABILITY with swollen ovaries and fluid sequestration into abdomen (and sometimes chest). Usually self-limited." },
  { id: "re247", category: "Vignettes", q: "26F with three first-trimester miscarriages and a single kidney: most likely reason?", a: "Congenital uterine abnormalities (the missing-kidney and Mullerian tract develop together - renal agenesis plus unicornuate/didelphys-type defects travel together). Also: 33F with regular periods, multiple past partners, husband with normal semen, unable to conceive 3 years -> hysterosalpingogram to assess tubal patency (prior PID scarring despite no ectopic history)." },
  { id: "re248", category: "Twinning", q: "Prenatal ultrasound shows one fetus much larger than the other. Twinning type and mechanism?", a: "Monochorionic-monoamniotic with twin-twin transfusion syndrome - one fetus siphons nutrients and blood flow from the twin." },
  // ===== REPRO: Vignette nuggets round 4 =====
  { id: "re249", category: "Pregnancy Heme", q: "24F with ITP is pregnant: what is the potential effect on the fetus?", a: "Fetal platelet destruction - maternal IgG against her own platelet GpIIb/IIIa can cross the placenta and attack the fetal platelets. Related normals: pregnancy Hb dropping to ~10.5 g/dL with MCV 87 is physiologic dilution, and gestational thrombocytopenia is the diagnosis only once platelets fall below 150,000/uL (a mild reduction is normal)." },
  { id: "re250", category: "Pregnancy Heme", q: "Pregnant woman on iron for three weeks: iron and ferritin normalize but microcytic anemia persists. Next step and what the electrophoresis shows?", a: "Hemoglobin electrophoresis - this is thalassemia (usually alpha trait: asymptomatic, discovered in pregnancy) because it is microcytic anemia non-responsive to iron. Electrophoresis shows HbA2 in beta-thalassemia minor; an African American patient with 95% HbA1 = iron deficiency anemia instead. Alpha-/beta-globin DNA testing is a wrong answer for the initial work-up." },
  { id: "re251", category: "Labor", q: "Shoulder dystocia with a McRoberts maneuver: the two named fetal risks?", a: "Clavicular fracture (anterior shoulder caught behind the pubic symphysis; McRoberts = hip flexion + suprapubic pressure) and Erb-Duchenne palsy - injury to the C5/C6 nerve roots leaving the arm pronated, adducted, and internally rotated. And the cause-of-bleeding switch: postpartum bleeding with a FIRM uterus after shoulder dystocia = vaginal laceration, NOT uterine atony." },
  { id: "re252", category: "Labor", q: "Uterine rupture: the two exam tells they actually write?", a: "1) Leopold maneuvers show fetal small parts above the fundus (with constant sharp pain, late decels, and a prior C-section history). 2) Fetal head palpated in the RUQ after oxytocin-driven contractions every 2 minutes with hypotension. Leopold maneuvers are abdominal palpatory maneuvers to determine fetal position and lie." },
  { id: "re253", category: "Vignettes", q: "27F five days after delivery has calf pain on dorsiflexion of the foot. Next diagnostic step and why?", a: "Duplex ultrasonography of the calf - a positive Homan sign for DVT in the hypercoagulable postpartum state." },
  { id: "re254", category: "Vulvovaginal", q: "5F with foul-smelling yellow discharge and spotting but no dysuria vs 82F with Alzheimer brought in with a 3-cm vaginal laceration?", a: "Child with foul discharge, mild vulvar erythema, no trauma = vaginal FOREIGN BODY (not abuse - abuse questions show lacerations). Elderly patient with a vaginal laceration + erythematous edematous perineal body = sexual assault." },
  { id: "re255", category: "Vignettes", q: "37F with dysuria and 20-50 WBCs/hpf whose week of TMP-SMX fails. Next best step, and the coitis rule?", a: "Urethral culture for CHLAMYDIA - if UTI treatment doesn't work, check for STIs. For recurrent post-coital UTIs, 'voiding immediately after coitus' is the prevention answer." },
  // ===== REPRO: Vignette nuggets round 5 =====
  { id: "re256", category: "Neonate", q: "A 28F diabetic at 37 weeks delivers a macrosomic neonate with NRDS. Which hormone in fetal serum is responsible?", a: "INSULIN - it inhibits surfactant production. Insulin does NOT cross the placenta; glucose does, and the fetus makes its own excess insulin in response to maternal diabetes. (Contrast the lecithin/sphingomyelin question: lecithin = dipalmitoyl phosphatidylcholine.)" },
  { id: "re257", category: "Neonate", q: "Steroids vs magnesium before premature delivery: the week-based rules?", a: "Steroids BEFORE 34 weeks (two boluses within 24 hours of delivery); at 34 0/7 to 36 6/7, one bolus. ADD MAGNESIUM if before 32 weeks (neonatal neuroprotection). Tocolytics are only used below 34 weeks to buy a few days for the steroid window - terbutaline, ritodrine, nifedipine." },
  { id: "re258", category: "STDs", q: "Which HPV types does Gardasil cover?", a: "6, 11, 16, and 18 (6/11 = warts; 16/18 = squamous cell carcinoma). Also: a 67F with T2DM whose vaginal candidiasis does not respond to topical miconazole - the reason it's refractory is the T2DM. Candidiasis can even present honestly as an itchy red introitus after recent antibiotics with NO classic discharge and a NORMAL KOH/wet mount." },
  { id: "re259", category: "HIV", q: "What is THE most important intervention to reduce vertical HIV transmission?", a: "HAART therapy during pregnancy to drive down maternal viral load - MORE important than avoiding breastfeeding, even though HIV is literally present in breastmilk. Plus intrapartum zidovudine to mom and zidovudine to the neonate within 12 hours of delivery (for 6 weeks)." },
  { id: "re260", category: "HepB", q: "A 27F at 14 weeks' gestation is NOT immune to HepB. Next best step?", a: "Vaccinate for HepB NOW. The neonatal rule: if mom is HepB(+), neonate gets BOTH HBIG and vaccine within 12 hours of birth; mom HepB negative = vaccine only within 12 hours; mom unknown = vaccine within 12 hours and HBIG within 7 DAYS if her test returns positive or stays unknown." },
  { id: "re261", category: "Syphilis", q: "19F with a painless vulvar ulcer and a NEGATIVE rapid plasma reagin. Next best step?", a: "REPEAT the rapid plasma reagin - RPR can be negative early in primary syphilis. (Compare the opposite formulation: positive VDRL at 1:4 with no symptoms -> answer is the FTA for confirmation.)" },
  { id: "re262", category: "Miscarriage", q: "35F bleeding at 6 weeks with beta-hCG 450 and no fetal pole on ultrasound; one week later beta-hCG is 90. Next best step?", a: "A THIRD measurement of beta-hCG within one week. This is a spontaneous abortion in progress; beta-hCG must be measured weekly until it goes negative (same surveillance rule as gestational trophoblastic disease / moles)." },
  { id: "re263", category: "Vignettes", q: "37F two days after C-section: erythematous incision, tender abdomen, normal vitals, two palpable groin lymph nodes. Diagnosis?", a: "Normal postoperative course. Surgery is trauma and the immune system generates a natural response - palpable nodes and mild incisional erythema are not endometritis." },
  { id: "re264", category: "Vignettes", q: "37F with vaginal bleeding + hydroureter. What kind of cancer?", a: "Cervical squamous cell carcinoma impinging on the ureter (vaginal bleeding + uni- or bilateral hydroureter/hydronephrosis)." },
];

export default reproQuestions;
